module.exports = {
  "add-club.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Add Club - Campusclub</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link active\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"clubs.html\" class=\"btn btn-secondary btn-sm\">← Back to Clubs</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    <div class=\"page-header\" style=\"max-width: 1000px; margin: 0 auto 1.5rem;\">\n      <div>\n        <h1 class=\"page-title\">Register a New Campus Club</h1>\n        <p class=\"page-subtitle\">Fill in the form to establish a club — see your card update in real-time on the right!</p>\n      </div>\n    </div>\n\n    <!-- 2-Column Layout with Live Card Preview -->\n    <div class=\"form-layout form-layout-with-preview\">\n      \n      <!-- Left: Form -->\n      <div class=\"form-card\">\n        <form id=\"addClubForm\">\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"clubName\">\n              Club Name <span class=\"required\">*</span>\n            </label>\n            <input type=\"text\" id=\"clubName\" class=\"form-control\" placeholder=\"e.g. Google Developer Student Club\" required>\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\">\n              Choose Club Logo Icon\n            </label>\n            <div id=\"logoPickerGrid\" class=\"logo-picker-grid\">\n              <button type=\"button\" class=\"logo-option-btn selected\" data-icon=\"💻\">💻</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"🤖\">🤖</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"🚀\">🚀</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"🎵\">🎵</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"📸\">📸</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"🎭\">🎭</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"⚽\">⚽</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"📚\">📚</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"🤝\">🤝</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"🎨\">🎨</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"♟️\">♟️</button>\n              <button type=\"button\" class=\"logo-option-btn\" data-icon=\"🔬\">🔬</button>\n            </div>\n            <input type=\"hidden\" id=\"selectedLogoIcon\" value=\"💻\">\n          </div>\n\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label class=\"form-label\" for=\"clubCategory\">\n                Category <span class=\"required\">*</span>\n              </label>\n              <select id=\"clubCategory\" class=\"form-control\" required>\n                <option value=\"Technical\">Technical</option>\n                <option value=\"Cultural\">Cultural</option>\n                <option value=\"Sports\">Sports</option>\n                <option value=\"Literary\">Literary</option>\n                <option value=\"Social\">Social / NSS</option>\n                <option value=\"Entrepreneurship\">Entrepreneurship</option>\n                <option value=\"Academic\">Academic</option>\n                <option value=\"Other\">Other</option>\n              </select>\n            </div>\n\n            <div class=\"form-group\">\n              <label class=\"form-label\" for=\"clubFounded\">\n                Founded Year <span class=\"required\">*</span>\n              </label>\n              <input type=\"number\" id=\"clubFounded\" class=\"form-control\" min=\"1950\" max=\"2099\" required>\n            </div>\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"clubCoordinator\">\n              Faculty Coordinator <span class=\"required\">*</span>\n            </label>\n            <input type=\"text\" id=\"clubCoordinator\" class=\"form-control\" placeholder=\"e.g. Dr. Priya Sharma, Dept of CSE\" required>\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"clubDesc\">\n              Description & Mission\n            </label>\n            <textarea id=\"clubDesc\" class=\"form-control\" rows=\"4\" placeholder=\"Briefly describe the vision, workshops, and objectives of the club...\"></textarea>\n            <div style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 0.3rem;\">\n              <span class=\"form-hint\">Shown on club cards and profile page.</span>\n              <span id=\"descCharCount\" class=\"char-counter\">0 characters</span>\n            </div>\n          </div>\n\n          <div class=\"form-actions\">\n            <a href=\"clubs.html\" class=\"btn btn-secondary\">Cancel</a>\n            <button type=\"submit\" class=\"btn btn-primary\">+ Create Club</button>\n          </div>\n        </form>\n      </div>\n\n      <!-- Right: Real-time Live Preview -->\n      <div class=\"live-preview-box\">\n        <div class=\"live-preview-title\">\n          <span>👁️</span> Live Card Preview\n        </div>\n        <div id=\"liveClubPreview\">\n          <!-- Populated in real-time by forms.js -->\n        </div>\n      </div>\n\n    </div>\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div><strong>Campusclub</strong> - College Club Management System</div>\n      <div>Built with Node.js, Express, MySQL & Vanilla JS</div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/forms.js\"></script>\n</body>\n</html>\n",
  "add-event.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Schedule Event - Campusclub</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link active\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"events.html\" class=\"btn btn-secondary btn-sm\">← Back to Events</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    <div class=\"page-header\" style=\"max-width: 1000px; margin: 0 auto 1.5rem;\">\n      <div>\n        <h1 class=\"page-title\">Schedule a Campus Event</h1>\n        <p class=\"page-subtitle\">Publish a workshop, hackathon, cultural show, or seminar — preview updates in real-time!</p>\n      </div>\n    </div>\n\n    <!-- 2-Column Layout with Live Card Preview -->\n    <div class=\"form-layout form-layout-with-preview\">\n      \n      <!-- Left: Event Form -->\n      <div class=\"form-card\">\n        <form id=\"addEventForm\">\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"eventClubSelect\">\n              Organizing Club <span class=\"required\">*</span>\n            </label>\n            <select id=\"eventClubSelect\" class=\"form-control\" required>\n              <option value=\"\">-- Loading Clubs... --</option>\n            </select>\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"eventTitle\">\n              Event Title <span class=\"required\">*</span>\n            </label>\n            <input type=\"text\" id=\"eventTitle\" class=\"form-control\" placeholder=\"e.g. National Hackathon 2026\" required>\n          </div>\n\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label class=\"form-label\" for=\"eventDateTime\">\n                Date & Time <span class=\"required\">*</span>\n              </label>\n              <input type=\"datetime-local\" id=\"eventDateTime\" class=\"form-control\" required>\n            </div>\n\n            <div class=\"form-group\">\n              <label class=\"form-label\" for=\"eventVenue\">\n                Venue <span class=\"required\">*</span>\n              </label>\n              <input type=\"text\" id=\"eventVenue\" class=\"form-control\" placeholder=\"e.g. Main Auditorium\" required>\n            </div>\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"eventDesc\">\n              Description & Highlights\n            </label>\n            <textarea id=\"eventDesc\" class=\"form-control\" rows=\"4\" placeholder=\"Event schedule, prizes, guidelines, and what attendees will learn...\"></textarea>\n          </div>\n\n          <div class=\"form-actions\">\n            <a href=\"events.html\" class=\"btn btn-secondary\">Cancel</a>\n            <button type=\"submit\" class=\"btn btn-primary\">+ Publish Event</button>\n          </div>\n        </form>\n      </div>\n\n      <!-- Right: Real-time Live Preview -->\n      <div class=\"live-preview-box\">\n        <div class=\"live-preview-title\">\n          <span>👁️</span> Live Event Ticket Preview\n        </div>\n        <div id=\"liveEventPreview\">\n          <!-- Populated in real-time by forms.js -->\n        </div>\n      </div>\n\n    </div>\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div><strong>Campusclub</strong> - College Club Management System</div>\n      <div>Built with Node.js, Express, MySQL & Vanilla JS</div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/forms.js\"></script>\n</body>\n</html>\n",
  "add-member.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Add Member - Campusclub</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link active\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"members.html\" class=\"btn btn-secondary btn-sm\">← Back to Members</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    <div class=\"page-header\" style=\"max-width: 680px; margin: 0 auto 1.5rem;\">\n      <div>\n        <h1 class=\"page-title\">Register Student Member</h1>\n        <p class=\"page-subtitle\">Add a college student profile so they can join clubs and register for events</p>\n      </div>\n    </div>\n\n    <div class=\"form-card\">\n      <form id=\"addMemberForm\">\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"memberName\">\n            Full Name <span class=\"required\">*</span>\n          </label>\n          <input type=\"text\" id=\"memberName\" class=\"form-control\" placeholder=\"e.g. Rahul Sharma\" required>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"memberUsn\">\n              USN / Student ID <span class=\"required\">*</span>\n            </label>\n            <input type=\"text\" id=\"memberUsn\" class=\"form-control\" placeholder=\"e.g. 1RV21CS045\" style=\"text-transform: uppercase;\" required>\n            <div class=\"form-hint\">Must be unique per student.</div>\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"memberEmail\">\n              College Email <span class=\"required\">*</span>\n            </label>\n            <input type=\"email\" id=\"memberEmail\" class=\"form-control\" placeholder=\"e.g. rahul.cs21@college.edu\" required>\n          </div>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"memberPhone\">\n              Phone Number\n            </label>\n            <input type=\"tel\" id=\"memberPhone\" class=\"form-control\" placeholder=\"e.g. +91 9876543210\">\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"memberSemester\">\n              Current Semester <span class=\"required\">*</span>\n            </label>\n            <select id=\"memberSemester\" class=\"form-control\" required>\n              <option value=\"1\">Semester 1</option>\n              <option value=\"2\">Semester 2</option>\n              <option value=\"3\">Semester 3</option>\n              <option value=\"4\">Semester 4</option>\n              <option value=\"5\" selected>Semester 5</option>\n              <option value=\"6\">Semester 6</option>\n              <option value=\"7\">Semester 7</option>\n              <option value=\"8\">Semester 8</option>\n            </select>\n          </div>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"memberCourse\">\n            Degree Course / Branch <span class=\"required\">*</span>\n          </label>\n          <input type=\"text\" id=\"memberCourse\" class=\"form-control\" placeholder=\"e.g. B.Tech Computer Science & Engg\" required>\n        </div>\n\n        <div class=\"form-actions\">\n          <a href=\"members.html\" class=\"btn btn-secondary\">Cancel</a>\n          <button type=\"submit\" class=\"btn btn-primary\">+ Register Student</button>\n        </div>\n      </form>\n    </div>\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div><strong>Campusclub</strong> - College Club Management System</div>\n      <div>Built with Node.js, Express, MySQL & Vanilla JS</div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/forms.js\"></script>\n</body>\n</html>\n",
  "club-details.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Club Details - Campusclub</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link active\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"add-club.html\" class=\"btn btn-primary btn-sm\">+ Add Club</a>\n        <a href=\"join-club.html\" class=\"btn btn-secondary btn-sm\">Join Club</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    <div id=\"clubDetailContainer\">\n      <div class=\"spinner\"></div>\n    </div>\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div><strong>Campusclub</strong> - College Club Management System</div>\n      <div>Built with Node.js, Express, MySQL & Vanilla JS</div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/club-details.js\"></script>\n</body>\n</html>\n",
  "clubs.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Clubs Directory - Campusclub</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link active\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"add-club.html\" class=\"btn btn-primary btn-sm\">+ Add Club</a>\n        <a href=\"join-club.html\" class=\"btn btn-secondary btn-sm\">Join Club</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    <div class=\"page-header\">\n      <div>\n        <h1 class=\"page-title\">Campus Clubs & Societies</h1>\n        <p class=\"page-subtitle\">Discover student organizations, explore events, manage details, and enroll members</p>\n      </div>\n      <div style=\"display: flex; gap: 0.65rem; flex-wrap: wrap;\">\n        <button onclick=\"seedSampleData()\" class=\"btn btn-secondary\" title=\"Load sample clubs, students, and events\">\n          🌱 Load Sample Data\n        </button>\n        <a href=\"add-club.html\" class=\"btn btn-primary\">+ Add New Club</a>\n      </div>\n    </div>\n\n    <!-- Category Filter Pills -->\n    <div id=\"categoryPills\" class=\"filter-pills\">\n      <button class=\"filter-pill active\">All</button>\n    </div>\n\n    <!-- Interactive Search and Sort Toolbar -->\n    <div class=\"toolbar\">\n      <div class=\"search-box\">\n        <span class=\"search-icon\">🔍</span>\n        <input type=\"text\" id=\"searchInput\" class=\"search-input\" placeholder=\"Search by name, coordinator, keywords...\">\n        <button id=\"searchClearBtn\" class=\"search-clear\" title=\"Clear search\">&times;</button>\n      </div>\n\n      <div style=\"display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap;\">\n        <span id=\"resultsCount\" style=\"font-size: 0.85rem; font-weight: 600; color: var(--text-muted);\">Loading clubs...</span>\n        <select id=\"sortSelect\" class=\"filter-select\">\n          <option value=\"name-asc\">Sort: Name (A-Z)</option>\n          <option value=\"name-desc\">Sort: Name (Z-A)</option>\n          <option value=\"members-desc\">Sort: Most Members</option>\n          <option value=\"year-desc\">Sort: Newest First</option>\n        </select>\n      </div>\n    </div>\n\n    <!-- Clubs Grid -->\n    <div id=\"clubsGrid\" class=\"cards-grid\">\n      <div class=\"spinner\"></div>\n    </div>\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div><strong>Campusclub</strong> - College Club Management System</div>\n      <div>Built with Node.js, Express, MySQL & Vanilla JS</div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/clubs.js\"></script>\n</body>\n</html>\n",
  "css/style.css": "/* ==========================================================================\n   Campusclub - College Club Management System\n   Ultra-Modern, Interactive & Professional Design System\n   ========================================================================== */\n\n@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@500;600;700;800;900&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');\n\n:root {\n  /* Brand Palette */\n  --primary: #4f46e5;         /* Vibrant Indigo */\n  --primary-hover: #4338ca;\n  --primary-light: #eef2ff;\n  --primary-glow: rgba(79, 70, 229, 0.28);\n\n  --secondary: #06b6d4;       /* Cyan */\n  --secondary-hover: #0891b2;\n  --accent: #8b5cf6;          /* Purple */\n  --accent-glow: rgba(139, 92, 246, 0.25);\n\n  --success: #10b981;\n  --success-bg: #ecfdf5;\n  --warning: #f59e0b;\n  --warning-bg: #fffbeb;\n  --danger: #ef4444;\n  --danger-hover: #dc2626;\n  --danger-bg: #fef2f2;\n\n  /* Surfaces & Neutrals */\n  --dark: #0f172a;            /* Slate 900 */\n  --dark-surface: #1e293b;    /* Slate 800 */\n  --text-main: #1e293b;\n  --text-muted: #64748b;\n  --text-light: #94a3b8;\n  --bg-body: #f8fafc;\n  --bg-card: #ffffff;\n  --border: #e2e8f0;\n  --border-focus: #6366f1;\n\n  /* Elevation Shadows */\n  --shadow-xs: 0 1px 2px rgba(15, 23, 42, 0.04);\n  --shadow-sm: 0 2px 4px rgba(15, 23, 42, 0.05);\n  --shadow: 0 8px 16px -4px rgba(15, 23, 42, 0.08), 0 3px 6px -2px rgba(15, 23, 42, 0.04);\n  --shadow-md: 0 14px 28px -6px rgba(15, 23, 42, 0.1), 0 6px 12px -3px rgba(15, 23, 42, 0.05);\n  --shadow-lg: 0 24px 44px -10px rgba(15, 23, 42, 0.14), 0 10px 18px -4px rgba(15, 23, 42, 0.06);\n  --shadow-glow: 0 0 20px var(--primary-glow);\n\n  --radius-xs: 6px;\n  --radius-sm: 10px;\n  --radius-md: 14px;\n  --radius-lg: 20px;\n  --radius-full: 9999px;\n\n  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;\n  --font-heading: 'Outfit', 'Plus Jakarta Sans', system-ui, sans-serif;\n}\n\n/* --------------------------------------------------------------------------\n   Global Reset & Base\n   -------------------------------------------------------------------------- */\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: var(--font-sans);\n  background-color: var(--bg-body);\n  color: var(--text-main);\n  line-height: 1.6;\n  display: flex;\n  flex-direction: column;\n  min-height: 100vh;\n  -webkit-font-smoothing: antialiased;\n  background-image: \n    radial-gradient(at 0% 0%, rgba(99, 102, 241, 0.04) 0px, transparent 50%),\n    radial-gradient(at 100% 100%, rgba(6, 182, 212, 0.04) 0px, transparent 50%);\n  background-attachment: fixed;\n}\n\nh1, h2, h3, h4, h5, h6 {\n  font-family: var(--font-heading);\n  letter-spacing: -0.02em;\n}\n\na {\n  color: var(--primary);\n  text-decoration: none;\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\na:hover {\n  color: var(--primary-hover);\n}\n\n/* --------------------------------------------------------------------------\n   Navigation Bar (Glassmorphic)\n   -------------------------------------------------------------------------- */\n.navbar {\n  background: rgba(255, 255, 255, 0.88);\n  backdrop-filter: blur(14px);\n  -webkit-backdrop-filter: blur(14px);\n  border-bottom: 1px solid rgba(226, 232, 240, 0.8);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  box-shadow: 0 4px 20px rgba(15, 23, 42, 0.03);\n  transition: all 0.3s ease;\n}\n\n.nav-container {\n  max-width: 1240px;\n  margin: 0 auto;\n  padding: 0.85rem 1.5rem;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  font-size: 1.4rem;\n  font-weight: 800;\n  color: var(--dark);\n  text-decoration: none;\n  font-family: var(--font-heading);\n}\n\n.brand-icon {\n  background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 50%, #06b6d4 100%);\n  color: white;\n  width: 42px;\n  height: 42px;\n  border-radius: var(--radius-md);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.35rem;\n  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.35);\n  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);\n}\n\n.brand:hover .brand-icon {\n  transform: rotate(-6deg) scale(1.08);\n}\n\n.brand-name {\n  letter-spacing: -0.03em;\n}\n\n.brand-name span {\n  background: linear-gradient(135deg, #4f46e5, #06b6d4);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n\n.nav-links {\n  display: flex;\n  align-items: center;\n  gap: 0.35rem;\n  list-style: none;\n}\n\n.nav-link {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  padding: 0.55rem 0.95rem;\n  color: var(--text-muted);\n  font-weight: 600;\n  font-size: 0.925rem;\n  border-radius: var(--radius-sm);\n  transition: all 0.2s ease;\n  position: relative;\n}\n\n.nav-link:hover {\n  color: var(--primary);\n  background-color: var(--primary-light);\n  transform: translateY(-1px);\n}\n\n.nav-link.active {\n  color: var(--primary);\n  background-color: var(--primary-light);\n  font-weight: 700;\n}\n\n.nav-link.active::after {\n  content: '';\n  position: absolute;\n  bottom: 4px;\n  left: 50%;\n  transform: translateX(-50%);\n  width: 16px;\n  height: 3px;\n  background: var(--primary);\n  border-radius: var(--radius-full);\n}\n\n.nav-cta {\n  display: flex;\n  align-items: center;\n  gap: 0.65rem;\n}\n\n.menu-toggle {\n  display: none;\n  background: white;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n  padding: 0.5rem 0.75rem;\n  font-size: 1.25rem;\n  cursor: pointer;\n  color: var(--dark);\n}\n\n/* --------------------------------------------------------------------------\n   Layout & Container\n   -------------------------------------------------------------------------- */\n.main-content {\n  flex: 1;\n  max-width: 1240px;\n  width: 100%;\n  margin: 0 auto;\n  padding: 2.25rem 1.5rem;\n  animation: fadeIn 0.4s ease;\n}\n\n@keyframes fadeIn {\n  from { opacity: 0; transform: translateY(6px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n.page-header {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1.25rem;\n  margin-bottom: 2rem;\n}\n\n.page-title {\n  font-size: 2.1rem;\n  font-weight: 800;\n  color: var(--dark);\n  line-height: 1.2;\n}\n\n.page-subtitle {\n  color: var(--text-muted);\n  font-size: 1rem;\n  margin-top: 0.35rem;\n  max-width: 650px;\n}\n\n/* --------------------------------------------------------------------------\n   Interactive Buttons\n   -------------------------------------------------------------------------- */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5rem;\n  padding: 0.65rem 1.35rem;\n  font-size: 0.935rem;\n  font-weight: 600;\n  font-family: var(--font-sans);\n  border-radius: var(--radius-sm);\n  border: 1px solid transparent;\n  cursor: pointer;\n  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);\n  text-decoration: none;\n  position: relative;\n  overflow: hidden;\n  user-select: none;\n}\n\n.btn:active {\n  transform: scale(0.97);\n}\n\n.btn-sm {\n  padding: 0.4rem 0.85rem;\n  font-size: 0.85rem;\n  border-radius: var(--radius-xs);\n}\n\n.btn-lg {\n  padding: 0.85rem 1.75rem;\n  font-size: 1.05rem;\n  border-radius: var(--radius-md);\n}\n\n/* Primary Button with vibrant gradient & glow */\n.btn-primary {\n  background: linear-gradient(135deg, #4f46e5 0%, #6366f1 100%);\n  color: white;\n  box-shadow: 0 4px 14px rgba(79, 70, 229, 0.35);\n}\n\n.btn-primary:hover {\n  background: linear-gradient(135deg, #4338ca 0%, #4f46e5 100%);\n  color: white;\n  box-shadow: 0 6px 20px rgba(79, 70, 229, 0.45);\n  transform: translateY(-2px);\n}\n\n/* Secondary Button */\n.btn-secondary {\n  background: #ffffff;\n  color: var(--text-main);\n  border-color: var(--border);\n  box-shadow: var(--shadow-xs);\n}\n\n.btn-secondary:hover {\n  background: #f8fafc;\n  border-color: #cbd5e1;\n  color: var(--primary);\n  transform: translateY(-1px);\n  box-shadow: var(--shadow-sm);\n}\n\n/* Success Button */\n.btn-success {\n  background: linear-gradient(135deg, #10b981 0%, #059669 100%);\n  color: white;\n  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.3);\n}\n\n.btn-success:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 6px 20px rgba(16, 185, 129, 0.42);\n  color: white;\n}\n\n/* Danger Button */\n.btn-danger {\n  background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);\n  color: white;\n  box-shadow: 0 4px 14px rgba(239, 68, 68, 0.3);\n}\n\n.btn-danger:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 6px 20px rgba(239, 68, 68, 0.4);\n  color: white;\n}\n\n.btn-outline-danger {\n  background: transparent;\n  color: var(--danger);\n  border-color: #fca5a5;\n}\n\n.btn-outline-danger:hover {\n  background: var(--danger-bg);\n  border-color: var(--danger);\n  color: var(--danger);\n  transform: translateY(-1px);\n}\n\n.btn-outline-primary {\n  background: transparent;\n  color: var(--primary);\n  border-color: #c7d2fe;\n}\n\n.btn-outline-primary:hover {\n  background: var(--primary-light);\n  border-color: var(--primary);\n  color: var(--primary-hover);\n  transform: translateY(-1px);\n}\n\n/* Ripple effect on click */\n.ripple {\n  position: absolute;\n  border-radius: 50%;\n  transform: scale(0);\n  animation: ripple-animation 0.6s linear;\n  background-color: rgba(255, 255, 255, 0.4);\n  pointer-events: none;\n}\n\n@keyframes ripple-animation {\n  to {\n    transform: scale(4);\n    opacity: 0;\n  }\n}\n\n/* --------------------------------------------------------------------------\n   Hero Section\n   -------------------------------------------------------------------------- */\n.hero {\n  background: linear-gradient(135deg, #0f172a 0%, #1e1b4b 45%, #312e81 85%, #4338ca 100%);\n  color: white;\n  border-radius: var(--radius-lg);\n  padding: 4rem 3rem;\n  margin-bottom: 2.75rem;\n  box-shadow: var(--shadow-lg), 0 0 50px rgba(79, 70, 229, 0.2);\n  position: relative;\n  overflow: hidden;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n}\n\n/* Animated decorative background orbs */\n.hero::before {\n  content: '';\n  position: absolute;\n  top: -80px;\n  right: -80px;\n  width: 360px;\n  height: 360px;\n  background: radial-gradient(circle, rgba(139, 92, 246, 0.35) 0%, rgba(6, 182, 212, 0.1) 60%, transparent 80%);\n  border-radius: 50%;\n  filter: blur(40px);\n  pointer-events: none;\n  animation: floatOrb 8s ease-in-out infinite alternate;\n}\n\n.hero::after {\n  content: '';\n  position: absolute;\n  bottom: -60px;\n  left: 30%;\n  width: 280px;\n  height: 280px;\n  background: radial-gradient(circle, rgba(79, 70, 229, 0.3) 0%, transparent 70%);\n  border-radius: 50%;\n  filter: blur(35px);\n  pointer-events: none;\n}\n\n@keyframes floatOrb {\n  0% { transform: translateY(0px) scale(1); }\n  100% { transform: translateY(-25px) scale(1.1); }\n}\n\n.hero-tagline {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  background: rgba(255, 255, 255, 0.12);\n  backdrop-filter: blur(8px);\n  padding: 0.4rem 1rem;\n  border-radius: var(--radius-full);\n  font-size: 0.85rem;\n  font-weight: 700;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  margin-bottom: 1.25rem;\n  border: 1px solid rgba(255, 255, 255, 0.15);\n}\n\n.hero-title {\n  font-size: 3rem;\n  font-weight: 800;\n  line-height: 1.15;\n  margin-bottom: 1.25rem;\n  max-width: 750px;\n  letter-spacing: -0.03em;\n}\n\n.hero-title .highlight {\n  background: linear-gradient(135deg, #a5b4fc 0%, #38bdf8 50%, #c084fc 100%);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n\n.hero-text {\n  font-size: 1.15rem;\n  color: #cbd5e1;\n  max-width: 640px;\n  margin-bottom: 2rem;\n  line-height: 1.65;\n}\n\n.hero-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 1rem;\n  position: relative;\n  z-index: 2;\n}\n\n/* Quick Search bar inside Hero */\n.hero-search-bar {\n  background: rgba(255, 255, 255, 0.15);\n  backdrop-filter: blur(12px);\n  border: 1px solid rgba(255, 255, 255, 0.25);\n  border-radius: var(--radius-md);\n  padding: 0.5rem;\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  max-width: 580px;\n  margin-top: 2rem;\n  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);\n}\n\n.hero-search-input {\n  flex: 1;\n  background: transparent;\n  border: none;\n  outline: none;\n  padding: 0.65rem 1rem;\n  color: white;\n  font-size: 1rem;\n  font-family: inherit;\n}\n\n.hero-search-input::placeholder {\n  color: #94a3b8;\n}\n\n/* --------------------------------------------------------------------------\n   Dashboard Animated Stats Grid\n   -------------------------------------------------------------------------- */\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 1.5rem;\n  margin-bottom: 3rem;\n}\n\n.stat-card {\n  background: var(--bg-card);\n  padding: 1.65rem;\n  border-radius: var(--radius-md);\n  border: 1px solid var(--border);\n  box-shadow: var(--shadow-sm);\n  display: flex;\n  align-items: center;\n  gap: 1.35rem;\n  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n  position: relative;\n  overflow: hidden;\n}\n\n.stat-card::after {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 3px;\n  background: transparent;\n  transition: background 0.3s ease;\n}\n\n.stat-card:hover {\n  transform: translateY(-4px);\n  box-shadow: var(--shadow-md);\n  border-color: #cbd5e1;\n}\n\n.stat-card:hover::after {\n  background: linear-gradient(90deg, var(--primary), var(--secondary));\n}\n\n.stat-icon {\n  width: 58px;\n  height: 58px;\n  border-radius: var(--radius-md);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.75rem;\n  flex-shrink: 0;\n  transition: transform 0.3s ease;\n}\n\n.stat-card:hover .stat-icon {\n  transform: scale(1.1) rotate(-4deg);\n}\n\n.stat-icon.clubs { background: linear-gradient(135deg, #ede9fe, #ddd6fe); color: #7c3aed; }\n.stat-icon.members { background: linear-gradient(135deg, #e0f2fe, #bae6fd); color: #0284c7; }\n.stat-icon.events { background: linear-gradient(135deg, #fef3c7, #fde68a); color: #d97706; }\n.stat-icon.regs { background: linear-gradient(135deg, #d1fae5, #a7f3d0); color: #059669; }\n\n.stat-info h3 {\n  font-size: 2.15rem;\n  font-weight: 800;\n  color: var(--dark);\n  line-height: 1;\n}\n\n.stat-info p {\n  color: var(--text-muted);\n  font-size: 0.9rem;\n  font-weight: 600;\n  margin-top: 0.3rem;\n}\n\n/* --------------------------------------------------------------------------\n   Filter & Interactive Toolbar\n   -------------------------------------------------------------------------- */\n.toolbar {\n  background: var(--bg-card);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 1.15rem 1.35rem;\n  margin-bottom: 2rem;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 1.25rem;\n  justify-content: space-between;\n  box-shadow: var(--shadow-xs);\n}\n\n.search-box {\n  flex: 1;\n  min-width: 260px;\n  position: relative;\n}\n\n.search-input {\n  width: 100%;\n  padding: 0.7rem 2.6rem 0.7rem 2.6rem;\n  border: 1.5px solid var(--border);\n  border-radius: var(--radius-sm);\n  font-size: 0.95rem;\n  font-family: inherit;\n  outline: none;\n  transition: all 0.2s ease;\n  background-color: #f8fafc;\n}\n\n.search-input:focus {\n  border-color: var(--primary);\n  background-color: #ffffff;\n  box-shadow: 0 0 0 4px var(--primary-glow);\n}\n\n.search-icon {\n  position: absolute;\n  left: 0.9rem;\n  top: 50%;\n  transform: translateY(-50%);\n  color: var(--text-muted);\n  pointer-events: none;\n  font-size: 1rem;\n}\n\n.search-clear {\n  position: absolute;\n  right: 0.85rem;\n  top: 50%;\n  transform: translateY(-50%);\n  background: none;\n  border: none;\n  color: var(--text-light);\n  font-size: 1.1rem;\n  cursor: pointer;\n  display: none;\n}\n\n.search-clear:hover {\n  color: var(--dark);\n}\n\n.filter-select {\n  padding: 0.7rem 1.15rem;\n  border: 1.5px solid var(--border);\n  border-radius: var(--radius-sm);\n  font-size: 0.925rem;\n  font-family: inherit;\n  background-color: white;\n  color: var(--text-main);\n  outline: none;\n  cursor: pointer;\n  transition: all 0.2s ease;\n  font-weight: 500;\n}\n\n.filter-select:focus {\n  border-color: var(--primary);\n  box-shadow: 0 0 0 4px var(--primary-glow);\n}\n\n/* Interactive Filter Pills Row */\n.filter-pills {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n  margin-bottom: 1.5rem;\n}\n\n.filter-pill {\n  padding: 0.45rem 1rem;\n  background: white;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-full);\n  font-size: 0.875rem;\n  font-weight: 600;\n  color: var(--text-muted);\n  cursor: pointer;\n  transition: all 0.2s ease;\n  user-select: none;\n}\n\n.filter-pill:hover {\n  background: var(--primary-light);\n  color: var(--primary);\n  border-color: #c7d2fe;\n}\n\n.filter-pill.active {\n  background: var(--primary);\n  color: white;\n  border-color: var(--primary);\n  box-shadow: 0 2px 8px rgba(79, 70, 229, 0.35);\n}\n\n/* --------------------------------------------------------------------------\n   Cards Grid & Card Components\n   -------------------------------------------------------------------------- */\n.cards-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));\n  gap: 1.75rem;\n}\n\n.card {\n  background: var(--bg-card);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n  position: relative;\n}\n\n.card:hover {\n  transform: translateY(-5px);\n  box-shadow: var(--shadow-md);\n  border-color: #cbd5e1;\n}\n\n/* Top colored accent indicator on card */\n.card::before {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 4px;\n  background: linear-gradient(90deg, #4f46e5, #06b6d4);\n  opacity: 0;\n  transition: opacity 0.3s ease;\n}\n\n.card:hover::before {\n  opacity: 1;\n}\n\n.card-header {\n  padding: 1.4rem 1.4rem 0.85rem;\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 0.85rem;\n}\n\n/* --------------------------------------------------------------------------\n   Club Logos & Emblems\n   -------------------------------------------------------------------------- */\n.club-logo-badge {\n  border-radius: var(--radius-md);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08);\n  border: 1.5px solid rgba(255, 255, 255, 0.65);\n  position: relative;\n  overflow: hidden;\n  user-select: none;\n  transition: transform 0.3s ease;\n}\n\n.card:hover .club-logo-badge {\n  transform: scale(1.06) rotate(-2deg);\n}\n\n.club-logo-sm {\n  width: 38px;\n  height: 38px;\n  font-size: 1.25rem;\n  border-radius: var(--radius-sm);\n}\n\n.club-logo-md {\n  width: 52px;\n  height: 52px;\n  font-size: 1.65rem;\n  border-radius: var(--radius-md);\n}\n\n.club-logo-lg {\n  width: 76px;\n  height: 76px;\n  font-size: 2.45rem;\n  border-radius: var(--radius-lg);\n  box-shadow: var(--shadow-md);\n}\n\n.club-title-row {\n  display: flex;\n  align-items: center;\n  gap: 0.85rem;\n}\n\n/* Logo Selector in Forms */\n.logo-picker-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(46px, 1fr));\n  gap: 0.5rem;\n  margin-top: 0.4rem;\n}\n\n.logo-option-btn {\n  width: 44px;\n  height: 44px;\n  border-radius: var(--radius-sm);\n  border: 1.5px solid var(--border);\n  background: white;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.35rem;\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.logo-option-btn:hover {\n  transform: scale(1.1);\n  border-color: var(--primary);\n  background: var(--primary-light);\n}\n\n.logo-option-btn.selected {\n  border-color: var(--primary);\n  background: var(--primary-light);\n  box-shadow: 0 0 0 3px var(--primary-glow);\n  transform: scale(1.08);\n}\n\n.card-title {\n  font-size: 1.28rem;\n  font-weight: 700;\n  color: var(--dark);\n  line-height: 1.3;\n}\n\n.card-body {\n  padding: 0 1.4rem 1.4rem;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n}\n\n.card-desc {\n  color: var(--text-muted);\n  font-size: 0.92rem;\n  line-height: 1.55;\n  margin-bottom: 1.15rem;\n  display: -webkit-box;\n  -webkit-line-clamp: 3;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n}\n\n.card-meta {\n  margin-top: auto;\n  border-top: 1px solid #f1f5f9;\n  padding-top: 1rem;\n  font-size: 0.875rem;\n  color: var(--text-muted);\n  display: flex;\n  flex-direction: column;\n  gap: 0.45rem;\n}\n\n.meta-item {\n  display: flex;\n  align-items: center;\n  gap: 0.45rem;\n}\n\n.card-footer {\n  background-color: #f8fafc;\n  border-top: 1px solid var(--border);\n  padding: 0.95rem 1.4rem;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 0.5rem;\n}\n\n/* --------------------------------------------------------------------------\n   Event Ticket / Calendar Box\n   -------------------------------------------------------------------------- */\n.event-card {\n  position: relative;\n  overflow: hidden;\n}\n\n.event-ticket-top {\n  display: flex;\n  gap: 1rem;\n  align-items: center;\n  margin-bottom: 1rem;\n}\n\n.calendar-box {\n  width: 54px;\n  height: 58px;\n  background: white;\n  border: 1.5px solid #e2e8f0;\n  border-radius: var(--radius-sm);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  flex-shrink: 0;\n  box-shadow: var(--shadow-xs);\n  overflow: hidden;\n}\n\n.calendar-month {\n  background: var(--primary);\n  color: white;\n  width: 100%;\n  font-size: 0.7rem;\n  font-weight: 800;\n  text-transform: uppercase;\n  padding: 2px 0;\n  letter-spacing: 0.05em;\n}\n\n.calendar-day {\n  font-size: 1.35rem;\n  font-weight: 800;\n  color: var(--dark);\n  line-height: 1.1;\n  margin-top: 2px;\n}\n\n.countdown-pill {\n  font-size: 0.775rem;\n  font-weight: 700;\n  padding: 0.2rem 0.65rem;\n  border-radius: var(--radius-full);\n  display: inline-flex;\n  align-items: center;\n  gap: 0.3rem;\n}\n\n.countdown-soon {\n  background: #fef3c7;\n  color: #92400e;\n}\n\n.countdown-today {\n  background: #fee2e2;\n  color: #991b1b;\n  animation: pulse 2s infinite;\n}\n\n.countdown-future {\n  background: #e0f2fe;\n  color: #0369a1;\n}\n\n@keyframes pulse {\n  0%, 100% { opacity: 1; }\n  50% { opacity: 0.6; }\n}\n\n/* --------------------------------------------------------------------------\n   Avatar Circles (for Students & Members)\n   -------------------------------------------------------------------------- */\n.avatar {\n  width: 38px;\n  height: 38px;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 700;\n  font-size: 0.85rem;\n  color: white;\n  background: linear-gradient(135deg, #6366f1, #8b5cf6);\n  flex-shrink: 0;\n  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);\n}\n\n.member-cell {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n}\n\n/* --------------------------------------------------------------------------\n   Badges\n   -------------------------------------------------------------------------- */\n.badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n  padding: 0.25rem 0.75rem;\n  border-radius: var(--radius-full);\n  font-size: 0.785rem;\n  font-weight: 700;\n  letter-spacing: 0.02em;\n}\n\n.badge-tech { background-color: #e0e7ff; color: #4338ca; border: 1px solid #c7d2fe; }\n.badge-cultural { background-color: #fce7f3; color: #be185d; border: 1px solid #fbcfe8; }\n.badge-sports { background-color: #dcfce7; color: #15803d; border: 1px solid #bbf7d0; }\n.badge-literary { background-color: #fef3c7; color: #b45309; border: 1px solid #fde68a; }\n.badge-social { background-color: #ffedd5; color: #c2410c; border: 1px solid #fed7aa; }\n.badge-other { background-color: #f1f5f9; color: #475569; border: 1px solid #e2e8f0; }\n\n.badge-role {\n  background: linear-gradient(135deg, #ede9fe, #f3e8ff);\n  color: #6d28d9;\n  border: 1px solid #ddd6fe;\n}\n\n.badge-role-lead {\n  background: linear-gradient(135deg, #fef3c7, #fde68a);\n  color: #92400e;\n  border: 1px solid #fcd34d;\n}\n\n/* --------------------------------------------------------------------------\n   Modern Table\n   -------------------------------------------------------------------------- */\n.table-container {\n  background: var(--bg-card);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  box-shadow: var(--shadow-sm);\n  overflow-x: auto;\n}\n\n.custom-table {\n  width: 100%;\n  border-collapse: collapse;\n  text-align: left;\n  font-size: 0.935rem;\n}\n\n.custom-table th {\n  background-color: #f8fafc;\n  color: var(--text-muted);\n  font-weight: 700;\n  padding: 1rem 1.4rem;\n  border-bottom: 1.5px solid var(--border);\n  font-size: 0.8rem;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n}\n\n.custom-table td {\n  padding: 1.1rem 1.4rem;\n  border-bottom: 1px solid var(--border);\n  color: var(--text-main);\n  vertical-align: middle;\n}\n\n.custom-table tr:last-child td {\n  border-bottom: none;\n}\n\n.custom-table tr {\n  transition: background-color 0.15s ease;\n}\n\n.custom-table tr:hover td {\n  background-color: #f8fafc;\n}\n\n/* --------------------------------------------------------------------------\n   Interactive Forms & Live Card Preview\n   -------------------------------------------------------------------------- */\n.form-layout {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 2rem;\n  max-width: 1000px;\n  margin: 0 auto;\n}\n\n@media (min-width: 900px) {\n  .form-layout-with-preview {\n    grid-template-columns: 1.25fr 1fr;\n    align-items: start;\n  }\n}\n\n.form-card {\n  background: var(--bg-card);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  box-shadow: var(--shadow-sm);\n  padding: 2.25rem;\n}\n\n.form-group {\n  margin-bottom: 1.4rem;\n}\n\n.form-label {\n  display: block;\n  font-size: 0.925rem;\n  font-weight: 700;\n  color: var(--dark);\n  margin-bottom: 0.45rem;\n}\n\n.form-label .required {\n  color: var(--danger);\n  margin-left: 0.2rem;\n}\n\n.form-control {\n  width: 100%;\n  padding: 0.75rem 1rem;\n  border: 1.5px solid var(--border);\n  border-radius: var(--radius-sm);\n  font-size: 0.95rem;\n  font-family: inherit;\n  color: var(--text-main);\n  background-color: #f8fafc;\n  outline: none;\n  transition: all 0.2s ease;\n}\n\n.form-control:focus {\n  border-color: var(--primary);\n  background-color: #ffffff;\n  box-shadow: 0 0 0 4px var(--primary-glow);\n}\n\ntextarea.form-control {\n  resize: vertical;\n  min-height: 110px;\n}\n\n.form-hint {\n  font-size: 0.825rem;\n  color: var(--text-muted);\n  margin-top: 0.4rem;\n}\n\n.char-counter {\n  font-size: 0.75rem;\n  color: var(--text-light);\n  text-align: right;\n  margin-top: 0.25rem;\n}\n\n.form-row {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 1.25rem;\n}\n\n.form-actions {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 0.85rem;\n  margin-top: 2rem;\n  padding-top: 1.5rem;\n  border-top: 1px solid var(--border);\n}\n\n/* Live Preview Side Box */\n.live-preview-box {\n  background: white;\n  border: 2px dashed #cbd5e1;\n  border-radius: var(--radius-md);\n  padding: 1.5rem;\n  position: sticky;\n  top: 90px;\n}\n\n.live-preview-title {\n  font-size: 0.85rem;\n  font-weight: 800;\n  color: var(--text-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  margin-bottom: 1rem;\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n}\n\n/* --------------------------------------------------------------------------\n   Club Details Page\n   -------------------------------------------------------------------------- */\n.detail-banner {\n  background: linear-gradient(135deg, #ffffff 0%, #f8fafc 100%);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-lg);\n  padding: 2.5rem;\n  margin-bottom: 2.5rem;\n  box-shadow: var(--shadow-sm);\n  position: relative;\n  overflow: hidden;\n}\n\n.detail-banner::before {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 6px;\n  height: 100%;\n  background: linear-gradient(180deg, var(--primary), var(--secondary));\n}\n\n.detail-header {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 1.5rem;\n  margin-bottom: 1rem;\n}\n\n.detail-title {\n  font-size: 2.35rem;\n  font-weight: 800;\n  color: var(--dark);\n  line-height: 1.15;\n}\n\n.detail-stats {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 2rem;\n  margin-top: 1.75rem;\n  padding-top: 1.5rem;\n  border-top: 1px solid var(--border);\n}\n\n.detail-stat {\n  display: flex;\n  align-items: center;\n  gap: 0.65rem;\n  color: var(--text-muted);\n  font-size: 0.95rem;\n}\n\n.detail-stat strong {\n  color: var(--dark);\n  font-size: 1.05rem;\n}\n\n.tabs-header {\n  display: flex;\n  gap: 0.75rem;\n  border-bottom: 2px solid var(--border);\n  margin-bottom: 2rem;\n}\n\n.tab-btn {\n  background: none;\n  border: none;\n  padding: 0.85rem 1.5rem;\n  font-size: 1.05rem;\n  font-weight: 700;\n  font-family: var(--font-heading);\n  color: var(--text-muted);\n  cursor: pointer;\n  position: relative;\n  bottom: -2px;\n  border-bottom: 3px solid transparent;\n  transition: all 0.2s ease;\n}\n\n.tab-btn:hover {\n  color: var(--primary);\n}\n\n.tab-btn.active {\n  color: var(--primary);\n  border-bottom-color: var(--primary);\n}\n\n/* --------------------------------------------------------------------------\n   Modal Window\n   -------------------------------------------------------------------------- */\n.modal-overlay {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: rgba(15, 23, 42, 0.65);\n  backdrop-filter: blur(6px);\n  -webkit-backdrop-filter: blur(6px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 200;\n  opacity: 0;\n  visibility: hidden;\n  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n.modal-overlay.active {\n  opacity: 1;\n  visibility: visible;\n}\n\n.modal {\n  background: white;\n  border-radius: var(--radius-lg);\n  box-shadow: var(--shadow-lg), 0 0 50px rgba(0, 0, 0, 0.2);\n  width: 90%;\n  max-width: 520px;\n  overflow: hidden;\n  transform: translateY(30px) scale(0.96);\n  transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);\n  border: 1px solid rgba(255, 255, 255, 0.2);\n}\n\n.modal-overlay.active .modal {\n  transform: translateY(0) scale(1);\n}\n\n.modal-header {\n  padding: 1.35rem 1.75rem;\n  border-bottom: 1px solid var(--border);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  background: #f8fafc;\n}\n\n.modal-title {\n  font-size: 1.25rem;\n  font-weight: 800;\n  color: var(--dark);\n}\n\n.modal-close {\n  background: none;\n  border: none;\n  font-size: 1.6rem;\n  line-height: 1;\n  color: var(--text-muted);\n  cursor: pointer;\n  transition: color 0.15s ease;\n}\n\n.modal-close:hover {\n  color: var(--danger);\n}\n\n.modal-body {\n  padding: 1.75rem;\n}\n\n.modal-footer {\n  padding: 1.15rem 1.75rem;\n  background-color: #f8fafc;\n  border-top: 1px solid var(--border);\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 0.85rem;\n}\n\n/* --------------------------------------------------------------------------\n   Toast Notifications\n   -------------------------------------------------------------------------- */\n.alert-container {\n  position: fixed;\n  top: 1.75rem;\n  right: 1.75rem;\n  z-index: 300;\n  display: flex;\n  flex-direction: column;\n  gap: 0.85rem;\n  max-width: 420px;\n}\n\n.alert {\n  padding: 1rem 1.35rem;\n  border-radius: var(--radius-md);\n  font-size: 0.95rem;\n  font-weight: 500;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1rem;\n  box-shadow: var(--shadow-lg);\n  animation: slideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n  backdrop-filter: blur(10px);\n}\n\n@keyframes slideIn {\n  from { transform: translateX(120%); opacity: 0; }\n  to { transform: translateX(0); opacity: 1; }\n}\n\n.alert-success {\n  background: #ecfdf5;\n  color: #065f46;\n  border-left: 5px solid var(--success);\n}\n\n.alert-danger {\n  background: #fef2f2;\n  color: #991b1b;\n  border-left: 5px solid var(--danger);\n}\n\n.alert-info {\n  background: #eef2ff;\n  color: #3730a3;\n  border-left: 5px solid var(--primary);\n}\n\n/* --------------------------------------------------------------------------\n   Empty States & Skeleton / Spinner\n   -------------------------------------------------------------------------- */\n.empty-state {\n  text-align: center;\n  padding: 4rem 2rem;\n  background: white;\n  border: 2px dashed var(--border);\n  border-radius: var(--radius-lg);\n  color: var(--text-muted);\n}\n\n.empty-icon {\n  font-size: 3.5rem;\n  margin-bottom: 1rem;\n}\n\n.empty-title {\n  font-size: 1.35rem;\n  font-weight: 800;\n  color: var(--dark);\n  margin-bottom: 0.45rem;\n}\n\n.spinner {\n  width: 42px;\n  height: 42px;\n  border: 3.5px solid var(--border);\n  border-top-color: var(--primary);\n  border-radius: 50%;\n  animation: spin 0.8s linear infinite;\n  margin: 3rem auto;\n}\n\n@keyframes spin {\n  to { transform: rotate(360deg); }\n}\n\n/* Confetti canvas on top */\n#confettiCanvas {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100vw;\n  height: 100vh;\n  pointer-events: none;\n  z-index: 999;\n}\n\n/* --------------------------------------------------------------------------\n   Footer\n   -------------------------------------------------------------------------- */\n.footer {\n  background-color: white;\n  border-top: 1px solid var(--border);\n  padding: 2.25rem 1.5rem;\n  margin-top: auto;\n  text-align: center;\n  color: var(--text-muted);\n  font-size: 0.925rem;\n}\n\n.footer-content {\n  max-width: 1240px;\n  margin: 0 auto;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1.25rem;\n}\n\n/* --------------------------------------------------------------------------\n   Responsive Media Queries\n   -------------------------------------------------------------------------- */\n@media (max-width: 820px) {\n  .menu-toggle {\n    display: block;\n  }\n\n  .nav-links {\n    display: none;\n    position: absolute;\n    top: 100%;\n    left: 0;\n    right: 0;\n    background: white;\n    flex-direction: column;\n    padding: 1.25rem 1.5rem;\n    border-bottom: 1px solid var(--border);\n    box-shadow: var(--shadow-md);\n    gap: 0.5rem;\n  }\n\n  .nav-links.show {\n    display: flex;\n  }\n\n  .form-row {\n    grid-template-columns: 1fr;\n  }\n\n  .hero-title {\n    font-size: 2.25rem;\n  }\n\n  .hero {\n    padding: 2.5rem 1.75rem;\n  }\n\n  .cards-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .footer-content {\n    flex-direction: column;\n    text-align: center;\n  }\n}\n",
  "edit-club.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Edit Club - Campusclub</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link active\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"clubs.html\" class=\"btn btn-secondary btn-sm\">← Back to Clubs</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    <div class=\"page-header\" style=\"max-width: 680px; margin: 0 auto 1.5rem;\">\n      <div>\n        <h1 class=\"page-title\">Edit Club Information</h1>\n        <p class=\"page-subtitle\">Update club metadata, coordinator, category, or description</p>\n      </div>\n    </div>\n\n    <div class=\"form-card\">\n      <form id=\"editClubForm\">\n        <input type=\"hidden\" id=\"editClubId\">\n\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"editClubName\">\n            Club Name <span class=\"required\">*</span>\n          </label>\n          <input type=\"text\" id=\"editClubName\" class=\"form-control\" required>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"editClubCategory\">\n              Category <span class=\"required\">*</span>\n            </label>\n            <select id=\"editClubCategory\" class=\"form-control\" required>\n              <option value=\"Technical\">Technical</option>\n              <option value=\"Cultural\">Cultural</option>\n              <option value=\"Sports\">Sports</option>\n              <option value=\"Literary\">Literary</option>\n              <option value=\"Social\">Social / NSS</option>\n              <option value=\"Entrepreneurship\">Entrepreneurship</option>\n              <option value=\"Academic\">Academic</option>\n              <option value=\"Other\">Other</option>\n            </select>\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"editClubFounded\">\n              Founded Year <span class=\"required\">*</span>\n            </label>\n            <input type=\"number\" id=\"editClubFounded\" class=\"form-control\" min=\"1950\" max=\"2099\" required>\n          </div>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"editClubCoordinator\">\n            Faculty Coordinator <span class=\"required\">*</span>\n          </label>\n          <input type=\"text\" id=\"editClubCoordinator\" class=\"form-control\" required>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"editClubDesc\">\n            Club Description / Objectives\n          </label>\n          <textarea id=\"editClubDesc\" class=\"form-control\" rows=\"4\"></textarea>\n        </div>\n\n        <div class=\"form-actions\">\n          <a href=\"clubs.html\" class=\"btn btn-secondary\">Cancel</a>\n          <button type=\"submit\" class=\"btn btn-primary\">💾 Save Changes</button>\n        </div>\n      </form>\n    </div>\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div><strong>Campusclub</strong> - College Club Management System</div>\n      <div>Built with Node.js, Express, MySQL & Vanilla JS</div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/forms.js\"></script>\n</body>\n</html>\n",
  "events.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Campus Events - Campusclub</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link active\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"add-event.html\" class=\"btn btn-primary btn-sm\">+ Add Event</a>\n        <a href=\"join-club.html\" class=\"btn btn-secondary btn-sm\">Join Club</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    <div class=\"page-header\">\n      <div>\n        <h1 class=\"page-title\">Campus Events & Workshops</h1>\n        <p class=\"page-subtitle\">Explore technical hackathons, cultural fests, workshops, and register with one click</p>\n      </div>\n      <div>\n        <a href=\"add-event.html\" class=\"btn btn-primary\">+ Schedule New Event</a>\n      </div>\n    </div>\n\n    <!-- Time Filter Pills -->\n    <div class=\"filter-pills\">\n      <button class=\"filter-pill active\" data-time=\"all\" onclick=\"selectTimeFilter('all')\">All Events</button>\n      <button class=\"filter-pill\" data-time=\"upcoming\" onclick=\"selectTimeFilter('upcoming')\">⚡ Upcoming Events</button>\n      <button class=\"filter-pill\" data-time=\"past\" onclick=\"selectTimeFilter('past')\">🏁 Past Events</button>\n    </div>\n\n    <!-- Interactive Search and Filter Toolbar -->\n    <div class=\"toolbar\">\n      <div class=\"search-box\">\n        <span class=\"search-icon\">🔍</span>\n        <input type=\"text\" id=\"eventSearchInput\" class=\"search-input\" placeholder=\"Search by event title, description, or venue...\">\n        <button id=\"eventSearchClear\" class=\"search-clear\" title=\"Clear search\">&times;</button>\n      </div>\n\n      <div style=\"display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap;\">\n        <span id=\"eventResultsCount\" style=\"font-size: 0.85rem; font-weight: 600; color: var(--text-muted);\">Loading events...</span>\n        \n        <select id=\"eventClubFilter\" class=\"filter-select\">\n          <option value=\"\">All Clubs</option>\n        </select>\n\n        <select id=\"eventSortSelect\" class=\"filter-select\">\n          <option value=\"date-asc\">Sort: Earliest First</option>\n          <option value=\"date-desc\">Sort: Latest First</option>\n          <option value=\"regs-desc\">Sort: Most Registered</option>\n          <option value=\"title-asc\">Sort: Title (A-Z)</option>\n        </select>\n      </div>\n    </div>\n\n    <!-- Events Grid -->\n    <div id=\"eventsGrid\" class=\"cards-grid\">\n      <div class=\"spinner\"></div>\n    </div>\n  </main>\n\n  <!-- Register Modal -->\n  <div id=\"registerModal\" class=\"modal-overlay\">\n    <div class=\"modal\">\n      <div class=\"modal-header\">\n        <h3 class=\"modal-title\">🎟️ Event Registration</h3>\n        <button class=\"modal-close\" onclick=\"closeRegisterModal()\">&times;</button>\n      </div>\n\n      <form id=\"modalRegisterForm\">\n        <div class=\"modal-body\">\n          <input type=\"hidden\" id=\"regEventId\">\n          \n          <div style=\"background: linear-gradient(135deg, #eef2ff, #e0e7ff); border: 1px solid #c7d2fe; padding: 1rem 1.25rem; border-radius: var(--radius-sm); margin-bottom: 1.5rem;\">\n            <div style=\"font-size: 0.775rem; color: #4338ca; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em;\">Selected Event</div>\n            <div id=\"modalEventTitle\" style=\"font-weight: 800; color: #1e1b4b; font-size: 1.15rem; margin-top: 0.2rem;\">Event Title</div>\n            <div id=\"modalEventDate\" style=\"font-size: 0.875rem; color: #4338ca; margin-top: 0.3rem;\">Date & Time</div>\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"regMemberSelect\">\n              Select Enrolled Student <span class=\"required\">*</span>\n            </label>\n            <select id=\"regMemberSelect\" class=\"form-control\" required>\n              <option value=\"\">-- Select Member --</option>\n            </select>\n            <div class=\"form-hint\">\n              Not registered in the system? <a href=\"add-member.html\" target=\"_blank\">Register as a student first</a>.\n            </div>\n          </div>\n        </div>\n\n        <div class=\"modal-footer\">\n          <button type=\"button\" class=\"btn btn-secondary\" onclick=\"closeRegisterModal()\">Cancel</button>\n          <button type=\"submit\" id=\"btnSubmitRegistration\" class=\"btn btn-primary\">Confirm Registration 🚀</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div><strong>Campusclub</strong> - College Club Management System</div>\n      <div>Built with Node.js, Express, MySQL & Vanilla JS</div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/events.js\"></script>\n</body>\n</html>\n",
  "index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Campusclub - College Club Management Portal</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Glassmorphic Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link active\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"add-club.html\" class=\"btn btn-primary btn-sm\">+ Add Club</a>\n        <a href=\"join-club.html\" class=\"btn btn-secondary btn-sm\">Join Club</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    \n    <!-- Ultra-Modern Hero Banner -->\n    <section class=\"hero\">\n      <div class=\"hero-tagline\">\n        <span>✨</span> Centralized Campus Activities & Communities\n      </div>\n      <h1 class=\"hero-title\">\n        Discover Clubs, Build Skills & <span class=\"highlight\">Make Campus Memories</span>\n      </h1>\n      <p class=\"hero-text\">\n        Join premier technical societies, cultural bands, coding hackathons, and sports teams.\n        Manage clubs, track memberships, and register for campus events with a single click.\n      </p>\n\n      <div class=\"hero-actions\">\n        <a href=\"clubs.html\" class=\"btn btn-primary btn-lg\">Explore Clubs →</a>\n        <a href=\"events.html\" class=\"btn btn-secondary btn-lg\">Browse Events & Register</a>\n        <a href=\"add-member.html\" class=\"btn btn-outline-primary btn-lg\" style=\"color: white; border-color: rgba(255,255,255,0.4);\">+ Register Student</a>\n      </div>\n\n      <!-- Quick Search Bar inside Hero -->\n      <form class=\"hero-search-bar\" onsubmit=\"event.preventDefault(); window.location.href='clubs.html?q=' + encodeURIComponent(document.getElementById('heroSearchInput').value);\">\n        <span style=\"font-size: 1.15rem; margin-left: 0.5rem;\">🔍</span>\n        <input type=\"text\" id=\"heroSearchInput\" class=\"hero-search-input\" placeholder=\"Search clubs (e.g. Coding, Robotics, Dance, Music)...\">\n        <button type=\"submit\" class=\"btn btn-primary btn-sm\" style=\"border-radius: var(--radius-sm);\">Search</button>\n      </form>\n    </section>\n\n    <!-- Animated Live Dashboard Statistics -->\n    <section>\n      <div style=\"display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 1.25rem;\">\n        <div>\n          <h2 style=\"font-size: 1.6rem; font-weight: 800; color: var(--dark);\">Live Campus Overview</h2>\n          <p style=\"color: var(--text-muted); font-size: 0.95rem;\">Real-time statistics across all societies and students</p>\n        </div>\n      </div>\n\n      <div class=\"stats-grid\">\n        <div class=\"stat-card\">\n          <div class=\"stat-icon clubs\">🏛️</div>\n          <div class=\"stat-info\">\n            <h3 id=\"statClubs\">0</h3>\n            <p>Active Clubs</p>\n          </div>\n        </div>\n\n        <div class=\"stat-card\">\n          <div class=\"stat-icon members\">👥</div>\n          <div class=\"stat-info\">\n            <h3 id=\"statMembers\">0</h3>\n            <p>Enrolled Students</p>\n          </div>\n        </div>\n\n        <div class=\"stat-card\">\n          <div class=\"stat-icon events\">🎉</div>\n          <div class=\"stat-info\">\n            <h3 id=\"statEvents\">0</h3>\n            <p>Campus Events</p>\n          </div>\n        </div>\n\n        <div class=\"stat-card\">\n          <div class=\"stat-icon regs\">🎟️</div>\n          <div class=\"stat-info\">\n            <h3 id=\"statRegistrations\">0</h3>\n            <p>Event Registrations</p>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- Interactive Category Pills Showcase -->\n    <section style=\"margin-bottom: 3.5rem;\">\n      <h2 style=\"font-size: 1.4rem; font-weight: 800; color: var(--dark); margin-bottom: 0.85rem;\">Explore by Category</h2>\n      <div class=\"filter-pills\" style=\"margin-bottom: 0;\">\n        <a href=\"clubs.html?category=Technical\" class=\"filter-pill\" style=\"font-size: 0.95rem; padding: 0.6rem 1.25rem;\">💻 Technical & Coding</a>\n        <a href=\"clubs.html?category=Cultural\" class=\"filter-pill\" style=\"font-size: 0.95rem; padding: 0.6rem 1.25rem;\">🎭 Cultural, Dance & Music</a>\n        <a href=\"clubs.html?category=Sports\" class=\"filter-pill\" style=\"font-size: 0.95rem; padding: 0.6rem 1.25rem;\">⚽ Sports & Fitness</a>\n        <a href=\"clubs.html?category=Literary\" class=\"filter-pill\" style=\"font-size: 0.95rem; padding: 0.6rem 1.25rem;\">📚 Literary & Debating</a>\n        <a href=\"clubs.html?category=Social\" class=\"filter-pill\" style=\"font-size: 0.95rem; padding: 0.6rem 1.25rem;\">🤝 Social Service & NSS</a>\n        <a href=\"clubs.html?category=Entrepreneurship\" class=\"filter-pill\" style=\"font-size: 0.95rem; padding: 0.6rem 1.25rem;\">🚀 E-Cell & Startups</a>\n      </div>\n    </section>\n\n    <!-- Quick Actions Action Center -->\n    <section style=\"margin-bottom: 3.5rem;\">\n      <div style=\"margin-bottom: 1.5rem;\">\n        <h2 style=\"font-size: 1.5rem; font-weight: 800; color: var(--dark);\">Quick Management Center</h2>\n        <p style=\"color: var(--text-muted); font-size: 0.95rem;\">Perform fast actions to administer campus organizations</p>\n      </div>\n\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem;\">\n        <div class=\"card\" style=\"padding: 1.75rem; text-align: center; border-radius: var(--radius-md);\">\n          <div style=\"font-size: 2.5rem; margin-bottom: 0.75rem;\">🏛️</div>\n          <h3 style=\"font-size: 1.25rem; font-weight: 700; margin-bottom: 0.4rem;\">Add a Club</h3>\n          <p style=\"color: var(--text-muted); font-size: 0.9rem; margin-bottom: 1.35rem;\">Establish an official student club with faculty coordinator.</p>\n          <a href=\"add-club.html\" class=\"btn btn-outline-primary\" style=\"margin-top: auto;\">+ New Club Form</a>\n        </div>\n\n        <div class=\"card\" style=\"padding: 1.75rem; text-align: center; border-radius: var(--radius-md);\">\n          <div style=\"font-size: 2.5rem; margin-bottom: 0.75rem;\">👤</div>\n          <h3 style=\"font-size: 1.25rem; font-weight: 700; margin-bottom: 0.4rem;\">Add a Member</h3>\n          <p style=\"color: var(--text-muted); font-size: 0.9rem; margin-bottom: 1.35rem;\">Register a college student with USN, branch, and semester.</p>\n          <a href=\"add-member.html\" class=\"btn btn-outline-primary\" style=\"margin-top: auto;\">+ New Member Form</a>\n        </div>\n\n        <div class=\"card\" style=\"padding: 1.75rem; text-align: center; border-radius: var(--radius-md);\">\n          <div style=\"font-size: 2.5rem; margin-bottom: 0.75rem;\">🤝</div>\n          <h3 style=\"font-size: 1.25rem; font-weight: 700; margin-bottom: 0.4rem;\">Join a Club</h3>\n          <p style=\"color: var(--text-muted); font-size: 0.9rem; margin-bottom: 1.35rem;\">Assign a student to a club and designate their role.</p>\n          <a href=\"join-club.html\" class=\"btn btn-outline-primary\" style=\"margin-top: auto;\">Assign Membership</a>\n        </div>\n\n        <div class=\"card\" style=\"padding: 1.75rem; text-align: center; border-radius: var(--radius-md);\">\n          <div style=\"font-size: 2.5rem; margin-bottom: 0.75rem;\">🎉</div>\n          <h3 style=\"font-size: 1.25rem; font-weight: 700; margin-bottom: 0.4rem;\">Schedule Event</h3>\n          <p style=\"color: var(--text-muted); font-size: 0.9rem; margin-bottom: 1.35rem;\">Organize a workshop, seminar, fest, or hackathon.</p>\n          <a href=\"add-event.html\" class=\"btn btn-outline-primary\" style=\"margin-top: auto;\">+ Schedule Event</a>\n        </div>\n      </div>\n    </section>\n\n    <!-- Featured Clubs Section -->\n    <section style=\"margin-bottom: 3.5rem;\">\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem;\">\n        <div>\n          <h2 style=\"font-size: 1.5rem; font-weight: 800; color: var(--dark);\">Featured Campus Clubs</h2>\n          <p style=\"color: var(--text-muted); font-size: 0.95rem;\">Active student groups making an impact</p>\n        </div>\n        <a href=\"clubs.html\" class=\"btn btn-secondary btn-sm\">View All Clubs →</a>\n      </div>\n\n      <div id=\"homeFeaturedClubs\" class=\"cards-grid\">\n        <div class=\"spinner\"></div>\n      </div>\n    </section>\n\n    <!-- Upcoming Events Section -->\n    <section>\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem;\">\n        <div>\n          <h2 style=\"font-size: 1.5rem; font-weight: 800; color: var(--dark);\">Upcoming Campus Events</h2>\n          <p style=\"color: var(--text-muted); font-size: 0.95rem;\">Don't miss upcoming workshops, fests, and competitions</p>\n        </div>\n        <a href=\"events.html\" class=\"btn btn-secondary btn-sm\">Browse All Events →</a>\n      </div>\n\n      <div id=\"homeUpcomingEvents\" class=\"cards-grid\">\n        <div class=\"spinner\"></div>\n      </div>\n    </section>\n\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div>\n        <strong>Campusclub</strong> - College Club Management System\n      </div>\n      <div>\n        Built with Node.js, Express, MySQL & Vanilla JS\n      </div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script>\n    document.addEventListener('DOMContentLoaded', async () => {\n      // 1. Fetch & Animate Stats\n      try {\n        const res = await fetch('/api/stats');\n        const data = await res.json();\n        if (data.success) {\n          animateCounter(document.getElementById('statClubs'), data.data.clubs);\n          animateCounter(document.getElementById('statMembers'), data.data.members);\n          animateCounter(document.getElementById('statEvents'), data.data.events);\n          animateCounter(document.getElementById('statRegistrations'), data.data.registrations);\n        }\n      } catch (err) {\n        console.error('Stats error:', err);\n      }\n\n      // 2. Fetch Featured Clubs Preview (top 3)\n      try {\n        const res = await fetch('/api/clubs');\n        const data = await res.json();\n        const container = document.getElementById('homeFeaturedClubs');\n        if (data.success && data.data.length > 0) {\n          const featured = data.data.slice(0, 3);\n          container.innerHTML = featured.map(c => `\n            <div class=\"card\">\n              <div class=\"card-header\">\n                <div class=\"club-title-row\">\n                  ${getClubLogoHTML(c, 'md')}\n                  <div>\n                    <h3 class=\"card-title\">${escapeHTML(c.club_name)}</h3>\n                    <div style=\"margin-top: 0.35rem;\">${getCategoryBadge(c.category)}</div>\n                  </div>\n                </div>\n              </div>\n              <div class=\"card-body\">\n                <p class=\"card-desc\">${escapeHTML(cleanClubDescription(c.description) || 'No description provided.')}</p>\n                <div class=\"card-meta\">\n                  <div class=\"meta-item\">\n                    <span>👤 Coordinator:</span>\n                    <strong>${escapeHTML(c.faculty_coordinator)}</strong>\n                  </div>\n                  <div class=\"meta-item\" style=\"justify-content: space-between; margin-top: 0.25rem;\">\n                    <span>👥 Members: <strong>${c.member_count}</strong></span>\n                    <span>🎉 Events: <strong>${c.event_count}</strong></span>\n                  </div>\n                </div>\n              </div>\n              <div class=\"card-footer\">\n                <a href=\"club-details.html?id=${c.club_id}\" class=\"btn btn-primary btn-sm\">View Details</a>\n                <a href=\"join-club.html?club_id=${c.club_id}\" class=\"btn btn-secondary btn-sm\">➕ Join</a>\n              </div>\n            </div>\n          `).join('');\n        } else {\n          container.innerHTML = `\n            <div class=\"empty-state\" style=\"grid-column: 1 / -1;\">\n              <div class=\"empty-icon\">🏛️</div>\n              <div class=\"empty-title\">No Clubs Yet</div>\n              <p>Be the first to create a campus club!</p>\n              <a href=\"add-club.html\" class=\"btn btn-primary btn-sm\" style=\"margin-top: 0.75rem;\">+ Add Club</a>\n            </div>\n          `;\n        }\n      } catch (err) {\n        console.error('Clubs preview error:', err);\n      }\n\n      // 3. Fetch Upcoming Events Preview\n      try {\n        const res = await fetch('/api/events');\n        const data = await res.json();\n        const container = document.getElementById('homeUpcomingEvents');\n        if (data.success && data.data.length > 0) {\n          const preview = data.data.slice(0, 3);\n          container.innerHTML = preview.map(e => {\n            const dateParts = getEventDateParts(e.event_date);\n            const countdown = getEventCountdownPill(e.event_date);\n            return `\n              <div class=\"card event-card\">\n                <div class=\"card-header\" style=\"padding-bottom: 0.5rem;\">\n                  <div class=\"event-ticket-top\" style=\"margin-bottom: 0;\">\n                    <div class=\"calendar-box\">\n                      <div class=\"calendar-month\">${dateParts.month}</div>\n                      <div class=\"calendar-day\">${dateParts.day}</div>\n                    </div>\n                    <div>\n                      <h3 class=\"card-title\">${escapeHTML(e.title)}</h3>\n                      <div style=\"margin-top: 0.3rem;\">${countdown}</div>\n                    </div>\n                  </div>\n                </div>\n                <div class=\"card-body\">\n                  <div style=\"font-size: 0.85rem; font-weight: 700; color: var(--primary); margin-bottom: 0.5rem;\">\n                    🏛️ ${escapeHTML(e.club_name)}\n                  </div>\n                  <p class=\"card-desc\">${escapeHTML(e.description || 'No description.')}</p>\n                  <div class=\"card-meta\">\n                    <div class=\"meta-item\">\n                      <span>📍 Venue:</span>\n                      <strong>${escapeHTML(e.venue)}</strong>\n                    </div>\n                    <div class=\"meta-item\">\n                      <span>🕒 Time:</span>\n                      <strong>${formatDateTime(e.event_date)}</strong>\n                    </div>\n                  </div>\n                </div>\n                <div class=\"card-footer\">\n                  <a href=\"events.html\" class=\"btn btn-primary btn-sm\">🎟️ Register Now</a>\n                  <a href=\"club-details.html?id=${e.club_id}\" class=\"btn btn-secondary btn-sm\">Club Info</a>\n                </div>\n              </div>\n            `;\n          }).join('');\n        } else {\n          container.innerHTML = `\n            <div class=\"empty-state\" style=\"grid-column: 1 / -1;\">\n              <div class=\"empty-icon\">🎉</div>\n              <div class=\"empty-title\">No Events Scheduled</div>\n              <p>Schedule your first club event to get students registered.</p>\n              <a href=\"add-event.html\" class=\"btn btn-primary btn-sm\" style=\"margin-top: 0.75rem;\">+ Schedule Event</a>\n            </div>\n          `;\n        }\n      } catch (err) {\n        console.error('Events preview error:', err);\n      }\n    });\n  </script>\n</body>\n</html>\n",
  "join-club.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Join Club - Campusclub</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"clubs.html\" class=\"btn btn-secondary btn-sm\">← Back to Clubs</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    <div class=\"page-header\" style=\"max-width: 680px; margin: 0 auto 1.5rem;\">\n      <div>\n        <h1 class=\"page-title\">Enroll Student in a Club</h1>\n        <p class=\"page-subtitle\">Assign a registered student member to a club and designate their role</p>\n      </div>\n    </div>\n\n    <div class=\"form-card\">\n      <form id=\"joinClubForm\">\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"joinMemberSelect\">\n            Select Student Member <span class=\"required\">*</span>\n          </label>\n          <select id=\"joinMemberSelect\" class=\"form-control\" required>\n            <option value=\"\">-- Loading Members... --</option>\n          </select>\n          <div class=\"form-hint\">\n            Not registered yet? <a href=\"add-member.html\" target=\"_blank\">Add a new member profile</a>.\n          </div>\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"joinClubSelect\">\n            Select Club <span class=\"required\">*</span>\n          </label>\n          <select id=\"joinClubSelect\" class=\"form-control\" required>\n            <option value=\"\">-- Loading Clubs... --</option>\n          </select>\n          <div class=\"form-hint\">\n            Missing club? <a href=\"add-club.html\" target=\"_blank\">Add the club first</a>.\n          </div>\n        </div>\n\n        <div class=\"form-row\">\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"joinRole\">\n              Role in Club <span class=\"required\">*</span>\n            </label>\n            <select id=\"joinRole\" class=\"form-control\" required>\n              <option value=\"Member\" selected>Member</option>\n              <option value=\"Core Member\">Core Member</option>\n              <option value=\"President\">President</option>\n              <option value=\"Vice President\">Vice President</option>\n              <option value=\"Secretary\">Secretary</option>\n              <option value=\"Treasurer\">Treasurer</option>\n              <option value=\"Technical Lead\">Technical Lead</option>\n              <option value=\"Event Coordinator\">Event Coordinator</option>\n              <option value=\"Media & PR Lead\">Media & PR Lead</option>\n            </select>\n          </div>\n\n          <div class=\"form-group\">\n            <label class=\"form-label\" for=\"joinDate\">\n              Date Joined <span class=\"required\">*</span>\n            </label>\n            <input type=\"date\" id=\"joinDate\" class=\"form-control\" required>\n          </div>\n        </div>\n\n        <div class=\"form-actions\">\n          <a href=\"clubs.html\" class=\"btn btn-secondary\">Cancel</a>\n          <button type=\"submit\" class=\"btn btn-primary\">+ Enroll Member</button>\n        </div>\n      </form>\n    </div>\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div><strong>Campusclub</strong> - College Club Management System</div>\n      <div>Built with Node.js, Express, MySQL & Vanilla JS</div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/forms.js\"></script>\n</body>\n</html>\n",
  "js/club-details.js": "// ============================================================================\n// club-details.js - Interactive Single Club Profile View\n// ============================================================================\n// Detailed view for a single club: faculty coordinator, description,\n// member leadership roster with avatars, and organized events with calendar blocks.\n// ============================================================================\n\nlet currentClubId = null;\nlet currentClubData = null;\n\nasync function loadClubDetails() {\n  const urlParams = new URLSearchParams(window.location.search);\n  currentClubId = urlParams.get('id');\n\n  if (!currentClubId) {\n    document.getElementById('clubDetailContainer').innerHTML = `\n      <div class=\"empty-state\">\n        <div class=\"empty-icon\">⚠️</div>\n        <div class=\"empty-title\">Club ID Missing</div>\n        <p>No club ID was specified in the URL.</p>\n        <a href=\"clubs.html\" class=\"btn btn-primary\" style=\"margin-top: 1rem;\">Back to Clubs</a>\n      </div>\n    `;\n    return;\n  }\n\n  try {\n    const res = await fetch(`/api/clubs/${currentClubId}`);\n    const result = await res.json();\n\n    if (!result.success || !result.data) {\n      throw new Error(result.message || 'Club not found');\n    }\n\n    currentClubData = result.data;\n    renderClubDetails(currentClubData);\n  } catch (err) {\n    console.error('Error loading club details:', err);\n    document.getElementById('clubDetailContainer').innerHTML = `\n      <div class=\"empty-state\">\n        <div class=\"empty-icon\">❌</div>\n        <div class=\"empty-title\">Error Loading Club</div>\n        <p>${escapeHTML(err.message)}</p>\n        <a href=\"clubs.html\" class=\"btn btn-primary\" style=\"margin-top: 1rem;\">Back to Clubs</a>\n      </div>\n    `;\n  }\n}\n\nfunction renderClubDetails(club) {\n  document.title = `${club.club_name} - Campusclub`;\n\n  const container = document.getElementById('clubDetailContainer');\n  if (!container) return;\n\n  const members = club.members || [];\n  const events = club.events || [];\n\n  container.innerHTML = `\n    <!-- Top Action Navigation -->\n    <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem; flex-wrap: wrap; gap: 0.75rem;\">\n      <a href=\"clubs.html\" class=\"btn btn-secondary btn-sm\">← Back to All Clubs</a>\n      <div style=\"display: flex; gap: 0.5rem; flex-wrap: wrap;\">\n        <button onclick=\"shareCurrentClub()\" class=\"btn btn-secondary btn-sm\">🔗 Share Club</button>\n        <a href=\"edit-club.html?id=${club.club_id}\" class=\"btn btn-secondary btn-sm\">✏️ Edit Club</a>\n        <button onclick=\"handleDeleteCurrentClub()\" class=\"btn btn-outline-danger btn-sm\">🗑️ Delete Club</button>\n      </div>\n    </div>\n\n    <!-- Club Header Banner -->\n    <div class=\"detail-banner\">\n      <div class=\"detail-header\">\n        <div style=\"display: flex; align-items: center; gap: 1.25rem;\">\n          ${getClubLogoHTML(club, 'lg')}\n          <div>\n            <div style=\"margin-bottom: 0.4rem;\">${getCategoryBadge(club.category)}</div>\n            <h1 class=\"detail-title\">${escapeHTML(club.club_name)}</h1>\n          </div>\n        </div>\n        <div style=\"display: flex; gap: 0.65rem; flex-wrap: wrap;\">\n          <a href=\"join-club.html?club_id=${club.club_id}\" class=\"btn btn-primary\">➕ Join This Club</a>\n          <a href=\"add-event.html?club_id=${club.club_id}\" class=\"btn btn-secondary\">🎉 Schedule Event</a>\n        </div>\n      </div>\n\n      <p style=\"font-size: 1.05rem; color: var(--text-muted); line-height: 1.65; margin-top: 1.25rem; max-width: 900px;\">\n        ${escapeHTML(cleanClubDescription(club.description) || 'No description provided for this club.')}\n      </p>\n\n      <div class=\"detail-stats\">\n        <div class=\"detail-stat\">\n          <span>👤 Faculty Coordinator:</span>\n          <strong>${escapeHTML(club.faculty_coordinator || 'Not Assigned')}</strong>\n        </div>\n        <div class=\"detail-stat\">\n          <span>📅 Established:</span>\n          <strong>${escapeHTML(club.founded_year || 'N/A')}</strong>\n        </div>\n        <div class=\"detail-stat\">\n          <span>👥 Total Enrolled:</span>\n          <strong>${members.length} Member(s)</strong>\n        </div>\n        <div class=\"detail-stat\">\n          <span>🎉 Events Organized:</span>\n          <strong>${events.length} Event(s)</strong>\n        </div>\n      </div>\n    </div>\n\n    <!-- Tabs: Members vs Events -->\n    <div class=\"tabs-header\">\n      <button class=\"tab-btn active\" id=\"tabMembersBtn\" onclick=\"switchTab('members')\">\n        👥 Members & Leadership (${members.length})\n      </button>\n      <button class=\"tab-btn\" id=\"tabEventsBtn\" onclick=\"switchTab('events')\">\n        🎉 Club Events (${events.length})\n      </button>\n    </div>\n\n    <!-- Tab 1: Members Content -->\n    <div id=\"tabMembersContent\">\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.25rem; flex-wrap: wrap; gap: 0.5rem;\">\n        <h3 style=\"font-size: 1.3rem; font-weight: 700;\">Club Roster</h3>\n        <a href=\"join-club.html?club_id=${club.club_id}\" class=\"btn btn-primary btn-sm\">+ Enroll Student in Club</a>\n      </div>\n      ${renderMembersTable(members)}\n    </div>\n\n    <!-- Tab 2: Events Content -->\n    <div id=\"tabEventsContent\" style=\"display: none;\">\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.25rem; flex-wrap: wrap; gap: 0.5rem;\">\n        <h3 style=\"font-size: 1.3rem; font-weight: 700;\">Events Organized by ${escapeHTML(club.club_name)}</h3>\n        <a href=\"add-event.html?club_id=${club.club_id}\" class=\"btn btn-primary btn-sm\">+ Add New Event</a>\n      </div>\n      ${renderEventsList(events)}\n    </div>\n  `;\n}\n\nfunction renderMembersTable(members) {\n  if (members.length === 0) {\n    return `\n      <div class=\"empty-state\">\n        <div class=\"empty-icon\">👥</div>\n        <div class=\"empty-title\">No Enrolled Members Yet</div>\n        <p>This club does not have any student members registered yet.</p>\n        <a href=\"join-club.html?club_id=${currentClubId}\" class=\"btn btn-primary btn-sm\" style=\"margin-top: 1rem;\">+ Join Club</a>\n      </div>\n    `;\n  }\n\n  return `\n    <div class=\"table-container\">\n      <table class=\"custom-table\">\n        <thead>\n          <tr>\n            <th>USN</th>\n            <th>Member Profile</th>\n            <th>Branch / Semester</th>\n            <th>Role</th>\n            <th>Joined On</th>\n            <th>Contact</th>\n          </tr>\n        </thead>\n        <tbody>\n          ${members.map(m => {\n            const isLead = /president|lead|head|secretary|coordinator/i.test(m.role || '');\n            const roleBadgeClass = isLead ? 'badge-role-lead' : 'badge-role';\n            const avatar = getAvatarHTML(m.full_name);\n\n            return `\n              <tr>\n                <td><strong>${escapeHTML(m.usn)}</strong></td>\n                <td>\n                  <div class=\"member-cell\">\n                    ${avatar}\n                    <div style=\"font-weight: 700;\">${escapeHTML(m.full_name)}</div>\n                  </div>\n                </td>\n                <td>${escapeHTML(m.course)} (Sem ${escapeHTML(m.semester)})</td>\n                <td>\n                  <span class=\"badge ${roleBadgeClass}\">\n                    ${isLead ? '⭐' : '🔹'} ${escapeHTML(m.role || 'Member')}\n                  </span>\n                </td>\n                <td>${formatDate(m.joined_on)}</td>\n                <td>\n                  <a href=\"mailto:${escapeHTML(m.email)}\" class=\"btn btn-secondary btn-sm\" style=\"font-size: 0.8rem;\">\n                    ✉️ Email\n                  </a>\n                </td>\n              </tr>\n            `;\n          }).join('')}\n        </tbody>\n      </table>\n    </div>\n  `;\n}\n\nfunction renderEventsList(events) {\n  if (events.length === 0) {\n    return `\n      <div class=\"empty-state\">\n        <div class=\"empty-icon\">🎉</div>\n        <div class=\"empty-title\">No Events Scheduled</div>\n        <p>This club has not posted any campus events yet.</p>\n        <a href=\"add-event.html?club_id=${currentClubId}\" class=\"btn btn-primary btn-sm\" style=\"margin-top: 1rem;\">+ Schedule First Event</a>\n      </div>\n    `;\n  }\n\n  return `\n    <div class=\"cards-grid\">\n      ${events.map(ev => {\n        const dateParts = getEventDateParts(ev.event_date);\n        const countdown = getEventCountdownPill(ev.event_date);\n\n        return `\n          <div class=\"card event-card\">\n            <div class=\"card-header\">\n              <div class=\"event-ticket-top\">\n                <div class=\"calendar-box\">\n                  <div class=\"calendar-month\">${dateParts.month}</div>\n                  <div class=\"calendar-day\">${dateParts.day}</div>\n                </div>\n                <div>\n                  <h4 class=\"card-title\">${escapeHTML(ev.title)}</h4>\n                  <div style=\"margin-top: 0.35rem;\">${countdown}</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"card-body\">\n              <p class=\"card-desc\">${escapeHTML(ev.description || 'No description provided.')}</p>\n              <div class=\"card-meta\">\n                <div class=\"meta-item\">\n                  <span>📅 Date:</span>\n                  <strong>${formatDateTime(ev.event_date)}</strong>\n                </div>\n                <div class=\"meta-item\">\n                  <span>📍 Venue:</span>\n                  <strong>${escapeHTML(ev.venue || 'Campus Auditorium')}</strong>\n                </div>\n                <div class=\"meta-item\">\n                  <span>🎟️ Attendees:</span>\n                  <strong>${ev.attendees_count || 0} registered</strong>\n                </div>\n              </div>\n            </div>\n            <div class=\"card-footer\">\n              <a href=\"events.html\" class=\"btn btn-primary btn-sm\">View on Events Page</a>\n            </div>\n          </div>\n        `;\n      }).join('')}\n    </div>\n  `;\n}\n\nfunction switchTab(tabName) {\n  const membersTab = document.getElementById('tabMembersContent');\n  const eventsTab = document.getElementById('tabEventsContent');\n  const membersBtn = document.getElementById('tabMembersBtn');\n  const eventsBtn = document.getElementById('tabEventsBtn');\n\n  if (tabName === 'members') {\n    membersTab.style.display = 'block';\n    eventsTab.style.display = 'none';\n    membersBtn.classList.add('active');\n    eventsBtn.classList.remove('active');\n  } else {\n    membersTab.style.display = 'none';\n    eventsTab.style.display = 'block';\n    eventsBtn.classList.add('active');\n    membersBtn.classList.remove('active');\n  }\n}\n\nfunction shareCurrentClub() {\n  if (!currentClubData) return;\n  copyToClipboard(window.location.href, `Link to ${currentClubData.club_name} copied!`);\n}\n\nasync function handleDeleteCurrentClub() {\n  if (!currentClubData) return;\n  const confirmed = confirm(`Are you sure you want to delete \"${currentClubData.club_name}\"?\\n\\nThis will remove the club, its memberships, and its events. This action cannot be undone.`);\n  if (!confirmed) return;\n\n  try {\n    const res = await fetch(`/api/clubs/${currentClubId}`, { method: 'DELETE' });\n    const result = await res.json();\n    if (!result.success) throw new Error(result.message);\n\n    alert(`Club \"${currentClubData.club_name}\" was deleted successfully.`);\n    window.location.href = 'clubs.html';\n  } catch (err) {\n    alert('Error deleting club: ' + err.message);\n  }\n}\n\ndocument.addEventListener('DOMContentLoaded', loadClubDetails);\n",
  "js/clubs.js": "// ============================================================================\n// clubs.js - Interactive Clubs Directory & Management\n// ============================================================================\n// Supports real-time search, category pill filtering, sorting, shareable links,\n// member/event counts, and safe deletion.\n// ============================================================================\n\nlet allClubs = [];\nlet activeCategory = '';\n\nasync function loadClubs() {\n  const container = document.getElementById('clubsGrid');\n  if (!container) return;\n\n  container.innerHTML = '<div class=\"spinner\"></div>';\n\n  try {\n    const res = await fetch('/api/clubs');\n    const result = await res.json();\n\n    if (!result.success) {\n      throw new Error(result.message || 'Failed to load clubs');\n    }\n\n    allClubs = result.data;\n\n    // Check if URL contains query parameter like ?category=... or ?q=...\n    const urlParams = new URLSearchParams(window.location.search);\n    const categoryParam = urlParams.get('category');\n    const queryParam = urlParams.get('q');\n\n    if (queryParam) {\n      const searchInput = document.getElementById('searchInput');\n      if (searchInput) searchInput.value = queryParam;\n    }\n\n    if (categoryParam) {\n      activeCategory = categoryParam;\n    }\n\n    renderCategoryPills(allClubs);\n    filterAndSortClubs();\n  } catch (err) {\n    console.error('Error loading clubs:', err);\n    container.innerHTML = `\n      <div class=\"empty-state\" style=\"grid-column: 1 / -1;\">\n        <div class=\"empty-icon\">⚠️</div>\n        <div class=\"empty-title\">Error Loading Clubs</div>\n        <p>${escapeHTML(err.message)}</p>\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"loadClubs()\" style=\"margin-top: 1rem;\">Retry</button>\n      </div>\n    `;\n  }\n}\n\n// Render interactive category filter pills\nfunction renderCategoryPills(clubs) {\n  const pillsContainer = document.getElementById('categoryPills');\n  if (!pillsContainer) return;\n\n  const categories = ['All', ...Array.from(new Set(clubs.map(c => c.category).filter(Boolean))).sort()];\n\n  pillsContainer.innerHTML = categories.map(cat => {\n    const isAll = cat === 'All';\n    const isActive = (isAll && !activeCategory) || activeCategory.toLowerCase() === cat.toLowerCase();\n    return `\n      <button class=\"filter-pill ${isActive ? 'active' : ''}\" onclick=\"selectCategory('${isAll ? '' : escapeHTML(cat)}')\">\n        ${escapeHTML(cat)}\n      </button>\n    `;\n  }).join('');\n}\n\nfunction selectCategory(cat) {\n  activeCategory = cat;\n  renderCategoryPills(allClubs);\n  filterAndSortClubs();\n}\n\nfunction renderClubs(clubs) {\n  const container = document.getElementById('clubsGrid');\n  const countBadge = document.getElementById('resultsCount');\n  if (!container) return;\n\n  if (countBadge) {\n    countBadge.textContent = `Showing ${clubs.length} of ${allClubs.length} clubs`;\n  }\n\n  if (clubs.length === 0) {\n    container.innerHTML = `\n      <div class=\"empty-state\" style=\"grid-column: 1 / -1;\">\n        <div class=\"empty-icon\">🔍</div>\n        <div class=\"empty-title\">No Matching Clubs Found</div>\n        <p>Try clearing your search or selecting a different category filter.</p>\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"resetFilters()\" style=\"margin-top: 1rem;\">Reset Filters</button>\n      </div>\n    `;\n    return;\n  }\n\n  container.innerHTML = clubs.map(club => `\n    <div class=\"card\">\n      <div class=\"card-header\">\n        <div class=\"club-title-row\">\n          ${getClubLogoHTML(club, 'md')}\n          <div>\n            <h3 class=\"card-title\">${escapeHTML(club.club_name)}</h3>\n            <div style=\"margin-top: 0.35rem;\">${getCategoryBadge(club.category)}</div>\n          </div>\n        </div>\n      </div>\n      <div class=\"card-body\">\n        <p class=\"card-desc\">${escapeHTML(cleanClubDescription(club.description) || 'No description provided.')}</p>\n        <div class=\"card-meta\">\n          <div class=\"meta-item\">\n            <span>👤 Coordinator:</span>\n            <strong>${escapeHTML(club.faculty_coordinator || 'Not Assigned')}</strong>\n          </div>\n          <div class=\"meta-item\">\n            <span>📅 Established:</span>\n            <strong>${escapeHTML(club.founded_year || 'N/A')}</strong>\n          </div>\n          <div class=\"meta-item\" style=\"justify-content: space-between; margin-top: 0.35rem;\">\n            <span class=\"badge badge-tech\">👥 ${club.member_count || 0} Members</span>\n            <span class=\"badge badge-sports\">🎉 ${club.event_count || 0} Events</span>\n          </div>\n        </div>\n      </div>\n      <div class=\"card-footer\">\n        <a href=\"club-details.html?id=${club.club_id}\" class=\"btn btn-primary btn-sm\">Explore Club →</a>\n        <div style=\"display: flex; gap: 0.4rem;\">\n          <button onclick=\"shareClub(${club.club_id}, '${escapeHTML(club.club_name)}')\" class=\"btn btn-secondary btn-sm\" title=\"Copy shareable link\">🔗</button>\n          <a href=\"edit-club.html?id=${club.club_id}\" class=\"btn btn-secondary btn-sm\" title=\"Edit Club\">✏️</a>\n          <button onclick=\"handleDeleteClub(${club.club_id}, '${escapeHTML(club.club_name)}')\" class=\"btn btn-outline-danger btn-sm\" title=\"Delete Club\">🗑️</button>\n        </div>\n      </div>\n    </div>\n  `).join('');\n}\n\nfunction filterAndSortClubs() {\n  const searchInput = document.getElementById('searchInput');\n  const sortSelect = document.getElementById('sortSelect');\n  const clearBtn = document.getElementById('searchClearBtn');\n\n  const searchTerm = searchInput ? searchInput.value.toLowerCase().trim() : '';\n  const sortMode = sortSelect ? sortSelect.value : 'name-asc';\n\n  if (clearBtn) {\n    clearBtn.style.display = searchTerm ? 'block' : 'none';\n  }\n\n  let filtered = allClubs.filter(club => {\n    const matchesSearch = \n      (club.club_name && club.club_name.toLowerCase().includes(searchTerm)) ||\n      (club.description && club.description.toLowerCase().includes(searchTerm)) ||\n      (club.faculty_coordinator && club.faculty_coordinator.toLowerCase().includes(searchTerm)) ||\n      (club.category && club.category.toLowerCase().includes(searchTerm));\n\n    const matchesCategory = !activeCategory || \n      (club.category && club.category.toLowerCase() === activeCategory.toLowerCase());\n\n    return matchesSearch && matchesCategory;\n  });\n\n  // Sorting\n  filtered.sort((a, b) => {\n    if (sortMode === 'name-asc') return (a.club_name || '').localeCompare(b.club_name || '');\n    if (sortMode === 'name-desc') return (b.club_name || '').localeCompare(a.club_name || '');\n    if (sortMode === 'members-desc') return (b.member_count || 0) - (a.member_count || 0);\n    if (sortMode === 'year-desc') return (b.founded_year || 0) - (a.founded_year || 0);\n    return 0;\n  });\n\n  renderClubs(filtered);\n}\n\nfunction clearSearch() {\n  const searchInput = document.getElementById('searchInput');\n  if (searchInput) {\n    searchInput.value = '';\n    filterAndSortClubs();\n  }\n}\n\nfunction resetFilters() {\n  const searchInput = document.getElementById('searchInput');\n  if (searchInput) searchInput.value = '';\n  activeCategory = '';\n  renderCategoryPills(allClubs);\n  filterAndSortClubs();\n}\n\nfunction shareClub(id, name) {\n  const url = `${window.location.origin}/club-details.html?id=${id}`;\n  copyToClipboard(url, `Link to ${name} copied to clipboard!`);\n}\n\nasync function handleDeleteClub(clubId, clubName) {\n  const confirmed = confirm(`Are you sure you want to delete \"${clubName}\"?\\n\\nThis will remove the club and its associated memberships and events. This action cannot be undone.`);\n  if (!confirmed) return;\n\n  try {\n    const res = await fetch(`/api/clubs/${clubId}`, { method: 'DELETE' });\n    const result = await res.json();\n\n    if (!result.success) throw new Error(result.message || 'Failed to delete club');\n\n    showAlert(`Club \"${clubName}\" was deleted successfully.`, 'success');\n    loadClubs();\n  } catch (err) {\n    showAlert('Error deleting club: ' + err.message, 'danger');\n  }\n}\n\nasync function seedSampleData() {\n  const confirmed = confirm('Do you want to load 8 official college clubs (GDSC, RoboTech, E-Cell, Crescendo, Blitz Sports, etc.), 12 student members with leadership roles, and campus events into the database?');\n  if (!confirmed) return;\n\n  showAlert('🌱 Seeding sample clubs and students...', 'info');\n\n  try {\n    const res = await fetch('/api/seed', { method: 'POST' });\n    const result = await res.json();\n    if (!result.success) throw new Error(result.message);\n\n    fireConfetti();\n    showAlert('🎉 Sample clubs, students, and events loaded successfully!', 'success');\n    loadClubs();\n  } catch (err) {\n    showAlert('Error loading sample data: ' + err.message, 'danger');\n  }\n}\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  loadClubs();\n\n  const searchInput = document.getElementById('searchInput');\n  if (searchInput) searchInput.addEventListener('input', filterAndSortClubs);\n\n  const sortSelect = document.getElementById('sortSelect');\n  if (sortSelect) sortSelect.addEventListener('change', filterAndSortClubs);\n\n  const clearBtn = document.getElementById('searchClearBtn');\n  if (clearBtn) clearBtn.addEventListener('click', clearSearch);\n});\n",
  "js/events.js": "// ============================================================================\n// events.js - Interactive Campus Events & 1-Click Registration\n// ============================================================================\n// Features calendar ticket blocks, relative countdown badges, interactive\n// search, filter pills, share links, and celebratory confetti registration.\n// ============================================================================\n\nlet allEvents = [];\nlet allMembersCache = [];\nlet activeTimeFilter = 'all'; // 'all', 'upcoming', 'past'\n\nasync function loadEvents() {\n  const container = document.getElementById('eventsGrid');\n  if (!container) return;\n\n  container.innerHTML = '<div class=\"spinner\"></div>';\n\n  try {\n    const res = await fetch('/api/events');\n    const result = await res.json();\n\n    if (!result.success) {\n      throw new Error(result.message || 'Failed to load events');\n    }\n\n    allEvents = result.data;\n    populateClubFilter(allEvents);\n    filterAndRenderEvents();\n  } catch (err) {\n    console.error('Error loading events:', err);\n    container.innerHTML = `\n      <div class=\"empty-state\" style=\"grid-column: 1 / -1;\">\n        <div class=\"empty-icon\">⚠️</div>\n        <div class=\"empty-title\">Error Loading Events</div>\n        <p>${escapeHTML(err.message)}</p>\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"loadEvents()\" style=\"margin-top: 1rem;\">Retry</button>\n      </div>\n    `;\n  }\n}\n\nfunction populateClubFilter(events) {\n  const select = document.getElementById('eventClubFilter');\n  if (!select) return;\n\n  const currentVal = select.value;\n  const clubs = Array.from(new Set(events.map(e => e.club_name).filter(Boolean))).sort();\n\n  select.innerHTML = '<option value=\"\">All Clubs</option>';\n  clubs.forEach(clubName => {\n    const opt = document.createElement('option');\n    opt.value = clubName;\n    opt.textContent = clubName;\n    if (clubName === currentVal) opt.selected = true;\n    select.appendChild(opt);\n  });\n}\n\nfunction selectTimeFilter(filter) {\n  activeTimeFilter = filter;\n  document.querySelectorAll('.filter-pill[data-time]').forEach(p => {\n    p.classList.toggle('active', p.getAttribute('data-time') === filter);\n  });\n  filterAndRenderEvents();\n}\n\nfunction renderEvents(events) {\n  const container = document.getElementById('eventsGrid');\n  const countBadge = document.getElementById('eventResultsCount');\n  if (!container) return;\n\n  if (countBadge) {\n    countBadge.textContent = `Showing ${events.length} of ${allEvents.length} events`;\n  }\n\n  if (events.length === 0) {\n    container.innerHTML = `\n      <div class=\"empty-state\" style=\"grid-column: 1 / -1;\">\n        <div class=\"empty-icon\">🎉</div>\n        <div class=\"empty-title\">No Events Found</div>\n        <p>No events match your current filter. Try selecting \"All Events\".</p>\n        <button class=\"btn btn-secondary btn-sm\" onclick=\"resetEventFilters()\" style=\"margin-top: 1rem;\">Reset Filters</button>\n      </div>\n    `;\n    return;\n  }\n\n  container.innerHTML = events.map(ev => {\n    const dateParts = getEventDateParts(ev.event_date);\n    const countdown = getEventCountdownPill(ev.event_date);\n\n    return `\n      <div class=\"card event-card\">\n        <div class=\"card-header\" style=\"padding-bottom: 0.65rem;\">\n          <div class=\"event-ticket-top\">\n            <div class=\"calendar-box\">\n              <div class=\"calendar-month\">${dateParts.month}</div>\n              <div class=\"calendar-day\">${dateParts.day}</div>\n            </div>\n            <div>\n              <h3 class=\"card-title\">${escapeHTML(ev.title)}</h3>\n              <div style=\"margin-top: 0.35rem; display: flex; align-items: center; gap: 0.4rem; flex-wrap: wrap;\">\n                ${countdown}\n                <span class=\"badge badge-tech\" style=\"font-size: 0.75rem;\">🏛️ ${escapeHTML(ev.club_name)}</span>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card-body\">\n          <p class=\"card-desc\">${escapeHTML(ev.description || 'No description provided for this event.')}</p>\n          <div class=\"card-meta\">\n            <div class=\"meta-item\">\n              <span>📅 Date & Time:</span>\n              <strong>${formatDateTime(ev.event_date)}</strong>\n            </div>\n            <div class=\"meta-item\">\n              <span>📍 Venue:</span>\n              <strong>${escapeHTML(ev.venue || 'Campus Auditorium')}</strong>\n            </div>\n            <div class=\"meta-item\" style=\"justify-content: space-between; margin-top: 0.25rem;\">\n              <span>🎟️ Attendees:</span>\n              <strong style=\"color: var(--primary);\">${ev.registered_count || 0} registered</strong>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card-footer\">\n          <button class=\"btn btn-primary btn-sm\" onclick=\"openRegisterModal(${ev.event_id}, '${escapeHTML(ev.title)}', '${formatDateTime(ev.event_date)}')\">\n            🎟️ Register Now\n          </button>\n          <div style=\"display: flex; gap: 0.4rem;\">\n            <button onclick=\"shareEvent(${ev.event_id}, '${escapeHTML(ev.title)}')\" class=\"btn btn-secondary btn-sm\" title=\"Share event\">🔗</button>\n            <a href=\"club-details.html?id=${ev.club_id}\" class=\"btn btn-secondary btn-sm\">Club Details</a>\n          </div>\n        </div>\n      </div>\n    `;\n  }).join('');\n}\n\nfunction filterAndRenderEvents() {\n  const searchInput = document.getElementById('eventSearchInput');\n  const clubFilter = document.getElementById('eventClubFilter');\n  const sortSelect = document.getElementById('eventSortSelect');\n  const clearBtn = document.getElementById('eventSearchClear');\n\n  const term = searchInput ? searchInput.value.toLowerCase().trim() : '';\n  const selectedClub = clubFilter ? clubFilter.value : '';\n  const sortMode = sortSelect ? sortSelect.value : 'date-asc';\n\n  if (clearBtn) {\n    clearBtn.style.display = term ? 'block' : 'none';\n  }\n\n  const now = new Date().getTime();\n\n  let filtered = allEvents.filter(ev => {\n    const matchesSearch = \n      (ev.title && ev.title.toLowerCase().includes(term)) ||\n      (ev.description && ev.description.toLowerCase().includes(term)) ||\n      (ev.venue && ev.venue.toLowerCase().includes(term)) ||\n      (ev.club_name && ev.club_name.toLowerCase().includes(term));\n\n    const matchesClub = !selectedClub || ev.club_name === selectedClub;\n\n    // Time filter\n    let matchesTime = true;\n    if (activeTimeFilter !== 'all' && ev.event_date) {\n      const eventTime = new Date(ev.event_date).getTime();\n      if (activeTimeFilter === 'upcoming') matchesTime = eventTime >= (now - 86400000); // within last 24h or future\n      if (activeTimeFilter === 'past') matchesTime = eventTime < (now - 86400000);\n    }\n\n    return matchesSearch && matchesClub && matchesTime;\n  });\n\n  // Sorting\n  filtered.sort((a, b) => {\n    const dateA = new Date(a.event_date || 0).getTime();\n    const dateB = new Date(b.event_date || 0).getTime();\n    if (sortMode === 'date-asc') return dateA - dateB;\n    if (sortMode === 'date-desc') return dateB - dateA;\n    if (sortMode === 'title-asc') return (a.title || '').localeCompare(b.title || '');\n    if (sortMode === 'regs-desc') return (b.registered_count || 0) - (a.registered_count || 0);\n    return 0;\n  });\n\n  renderEvents(filtered);\n}\n\nfunction resetEventFilters() {\n  const searchInput = document.getElementById('eventSearchInput');\n  if (searchInput) searchInput.value = '';\n  const clubFilter = document.getElementById('eventClubFilter');\n  if (clubFilter) clubFilter.value = '';\n  selectTimeFilter('all');\n}\n\nfunction shareEvent(id, title) {\n  const url = `${window.location.origin}/events.html?event_id=${id}`;\n  copyToClipboard(url, `Link to \"${title}\" copied to clipboard!`);\n}\n\n// ----------------------------------------------------------------------------\n// Event Registration Modal Logic\n// ----------------------------------------------------------------------------\nasync function openRegisterModal(eventId, eventTitle, eventDate) {\n  document.getElementById('modalEventTitle').textContent = eventTitle;\n  document.getElementById('modalEventDate').textContent = eventDate;\n  document.getElementById('regEventId').value = eventId;\n\n  const memberSelect = document.getElementById('regMemberSelect');\n  memberSelect.innerHTML = '<option value=\"\">-- Loading Members... --</option>';\n\n  const modal = document.getElementById('registerModal');\n  modal.classList.add('active');\n\n  try {\n    if (allMembersCache.length === 0) {\n      const res = await fetch('/api/members');\n      const data = await res.json();\n      allMembersCache = data.data || [];\n    }\n\n    if (allMembersCache.length === 0) {\n      memberSelect.innerHTML = '<option value=\"\">No members registered yet. Please add a member first.</option>';\n      return;\n    }\n\n    memberSelect.innerHTML = '<option value=\"\">-- Select Member / Student --</option>' + \n      allMembersCache.map(m => `\n        <option value=\"${m.member_id}\">\n          ${escapeHTML(m.full_name)} (${escapeHTML(m.usn)} - ${escapeHTML(m.course)})\n        </option>\n      `).join('');\n  } catch (err) {\n    console.error('Error loading members for registration:', err);\n    memberSelect.innerHTML = '<option value=\"\">Failed to load members</option>';\n  }\n}\n\nfunction closeRegisterModal() {\n  const modal = document.getElementById('registerModal');\n  if (modal) modal.classList.remove('active');\n  const form = document.getElementById('modalRegisterForm');\n  if (form) form.reset();\n}\n\nasync function submitEventRegistration(e) {\n  e.preventDefault();\n\n  const eventId = document.getElementById('regEventId').value;\n  const memberId = document.getElementById('regMemberSelect').value;\n\n  if (!eventId || !memberId) {\n    showAlert('Please select a student member to register.', 'danger');\n    return;\n  }\n\n  const submitBtn = document.getElementById('btnSubmitRegistration');\n  if (submitBtn) {\n    submitBtn.disabled = true;\n    submitBtn.textContent = 'Registering...';\n  }\n\n  try {\n    const res = await fetch('/api/registrations', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({\n        event_id: eventId,\n        member_id: memberId,\n        registered_on: new Date().toISOString()\n      })\n    });\n\n    const result = await res.json();\n\n    if (!result.success) throw new Error(result.message || 'Registration failed');\n\n    // CELEBRATORY CONFETTI BURST! 🎊\n    fireConfetti();\n    showAlert('🎉 ' + (result.message || 'Registration successful!'), 'success');\n    closeRegisterModal();\n    loadEvents();\n  } catch (err) {\n    showAlert(err.message, 'danger');\n  } finally {\n    if (submitBtn) {\n      submitBtn.disabled = false;\n      submitBtn.textContent = 'Confirm Registration';\n    }\n  }\n}\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  loadEvents();\n\n  const searchInput = document.getElementById('eventSearchInput');\n  if (searchInput) searchInput.addEventListener('input', filterAndRenderEvents);\n\n  const clubFilter = document.getElementById('eventClubFilter');\n  if (clubFilter) clubFilter.addEventListener('change', filterAndRenderEvents);\n\n  const sortSelect = document.getElementById('eventSortSelect');\n  if (sortSelect) sortSelect.addEventListener('change', filterAndRenderEvents);\n\n  const clearBtn = document.getElementById('eventSearchClear');\n  if (clearBtn) clearBtn.addEventListener('click', () => {\n    if (searchInput) {\n      searchInput.value = '';\n      filterAndRenderEvents();\n    }\n  });\n\n  const regForm = document.getElementById('modalRegisterForm');\n  if (regForm) regForm.addEventListener('submit', submitEventRegistration);\n\n  const modal = document.getElementById('registerModal');\n  if (modal) {\n    modal.addEventListener('click', (e) => {\n      if (e.target === modal) closeRegisterModal();\n    });\n  }\n});\n",
  "js/forms.js": "// ============================================================================\n// forms.js - Interactive Form Handlers with Real-Time Card Previews\n// ============================================================================\n// Manages validation, dynamic dropdown population, real-time live preview cards,\n// character counters, and celebratory submission feedback.\n// ============================================================================\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  if (document.getElementById('addClubForm')) initAddClubForm();\n  if (document.getElementById('editClubForm')) initEditClubForm();\n  if (document.getElementById('addMemberForm')) initAddMemberForm();\n  if (document.getElementById('addEventForm')) initAddEventForm();\n  if (document.getElementById('joinClubForm')) initJoinClubForm();\n});\n\n// ----------------------------------------------------------------------------\n// 1. ADD CLUB FORM with Live Preview & Character Counter\n// ----------------------------------------------------------------------------\nfunction initAddClubForm() {\n  const form = document.getElementById('addClubForm');\n  const foundedInput = document.getElementById('clubFounded');\n  if (foundedInput && !foundedInput.value) {\n    foundedInput.value = new Date().getFullYear();\n  }\n\n  // Real-time Live Preview\n  const nameInput = document.getElementById('clubName');\n  const catInput = document.getElementById('clubCategory');\n  const coordInput = document.getElementById('clubCoordinator');\n  const descInput = document.getElementById('clubDesc');\n  const previewCard = document.getElementById('liveClubPreview');\n  const charCounter = document.getElementById('descCharCount');\n  const logoInput = document.getElementById('selectedLogoIcon');\n\n  // Logo picker buttons\n  const logoBtns = document.querySelectorAll('.logo-option-btn');\n  logoBtns.forEach(btn => {\n    btn.addEventListener('click', () => {\n      logoBtns.forEach(b => b.classList.remove('selected'));\n      btn.classList.add('selected');\n      if (logoInput) logoInput.value = btn.getAttribute('data-icon');\n      updatePreview();\n    });\n  });\n\n  function updatePreview() {\n    if (!previewCard) return;\n    const name = nameInput.value.trim() || 'Club Name Preview';\n    const cat = catInput.value || 'Technical';\n    const coord = coordInput.value.trim() || 'Faculty Coordinator Name';\n    const year = (foundedInput && foundedInput.value) ? foundedInput.value : new Date().getFullYear();\n    const desc = descInput.value.trim() || 'Your club description will appear right here as you type...';\n    const icon = logoInput ? logoInput.value : '💻';\n\n    const dummyClub = {\n      club_name: name,\n      category: cat,\n      description: `[icon:${icon}] ${desc}`\n    };\n\n    previewCard.innerHTML = `\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div class=\"club-title-row\">\n            ${getClubLogoHTML(dummyClub, 'md')}\n            <div>\n              <h3 class=\"card-title\">${escapeHTML(name)}</h3>\n              <div style=\"margin-top: 0.35rem;\">${getCategoryBadge(cat)}</div>\n            </div>\n          </div>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"card-desc\">${escapeHTML(desc)}</p>\n          <div class=\"card-meta\">\n            <div class=\"meta-item\"><span>👤 Coordinator:</span> <strong>${escapeHTML(coord)}</strong></div>\n            <div class=\"meta-item\"><span>📅 Established:</span> <strong>${escapeHTML(year)}</strong></div>\n            <div class=\"meta-item\" style=\"justify-content: space-between; margin-top: 0.25rem;\">\n              <span class=\"badge badge-tech\">👥 0 Members</span>\n              <span class=\"badge badge-sports\">🎉 0 Events</span>\n            </div>\n          </div>\n        </div>\n        <div class=\"card-footer\">\n          <span class=\"btn btn-primary btn-sm\" style=\"pointer-events: none; opacity: 0.7;\">Explore Club</span>\n        </div>\n      </div>\n    `;\n\n    if (charCounter) {\n      charCounter.textContent = `${descInput.value.length} characters`;\n    }\n  }\n\n  if (nameInput) nameInput.addEventListener('input', updatePreview);\n  if (catInput) catInput.addEventListener('change', updatePreview);\n  if (coordInput) coordInput.addEventListener('input', updatePreview);\n  if (foundedInput) foundedInput.addEventListener('input', updatePreview);\n  if (descInput) descInput.addEventListener('input', updatePreview);\n  updatePreview();\n\n  form.addEventListener('submit', async (e) => {\n    e.preventDefault();\n\n    const submitBtn = form.querySelector('button[type=\"submit\"]');\n    const originalText = submitBtn.textContent;\n    submitBtn.disabled = true;\n    submitBtn.textContent = 'Creating Club...';\n\n    const selectedIcon = logoInput ? logoInput.value : '💻';\n    const payload = {\n      club_name: nameInput.value.trim(),\n      category: catInput.value,\n      faculty_coordinator: coordInput.value.trim(),\n      founded_year: foundedInput.value,\n      description: `[icon:${selectedIcon}] ${descInput.value.trim()}`\n    };\n\n    try {\n      const res = await fetch('/api/clubs', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(payload)\n      });\n      const data = await res.json();\n\n      if (!data.success) throw new Error(data.message || 'Failed to create club');\n\n      fireConfetti();\n      showAlert('🎉 ' + (data.message || 'Club created successfully!'), 'success');\n      form.reset();\n\n      setTimeout(() => {\n        window.location.href = 'clubs.html';\n      }, 1100);\n    } catch (err) {\n      console.error('Error adding club:', err);\n      showAlert(err.message, 'danger');\n    } finally {\n      submitBtn.disabled = false;\n      submitBtn.textContent = originalText;\n    }\n  });\n}\n\n// ----------------------------------------------------------------------------\n// 2. EDIT CLUB FORM\n// ----------------------------------------------------------------------------\nasync function initEditClubForm() {\n  const form = document.getElementById('editClubForm');\n  const urlParams = new URLSearchParams(window.location.search);\n  const clubId = urlParams.get('id');\n\n  if (!clubId) {\n    showAlert('No club ID specified for editing.', 'danger');\n    return;\n  }\n\n  try {\n    const res = await fetch(`/api/clubs/${clubId}`);\n    const data = await res.json();\n\n    if (!data.success || !data.data) throw new Error(data.message || 'Club not found');\n\n    const club = data.data;\n    let existingIcon = '';\n    const match = (club.description || '').match(/\\[icon:([^\\]]+)\\]/);\n    if (match) existingIcon = match[1];\n\n    document.getElementById('editClubId').value = club.club_id;\n    document.getElementById('editClubName').value = club.club_name || '';\n    document.getElementById('editClubCategory').value = club.category || 'Technical';\n    document.getElementById('editClubCoordinator').value = club.faculty_coordinator || '';\n    document.getElementById('editClubFounded').value = club.founded_year || '';\n    document.getElementById('editClubDesc').value = cleanClubDescription(club.description) || '';\n  } catch (err) {\n    showAlert('Error loading club data: ' + err.message, 'danger');\n  }\n\n  form.addEventListener('submit', async (e) => {\n    e.preventDefault();\n\n    const submitBtn = form.querySelector('button[type=\"submit\"]');\n    const originalText = submitBtn.textContent;\n    submitBtn.disabled = true;\n    submitBtn.textContent = 'Saving Changes...';\n\n    const match = (document.getElementById('editClubDesc').value || '').match(/\\[icon:([^\\]]+)\\]/);\n    const iconPrefix = match ? '' : (existingIcon ? `[icon:${existingIcon}] ` : '');\n\n    const payload = {\n      club_name: document.getElementById('editClubName').value.trim(),\n      category: document.getElementById('editClubCategory').value,\n      faculty_coordinator: document.getElementById('editClubCoordinator').value.trim(),\n      founded_year: document.getElementById('editClubFounded').value,\n      description: `${iconPrefix}${document.getElementById('editClubDesc').value.trim()}`\n    };\n\n    try {\n      const res = await fetch(`/api/clubs/${clubId}`, {\n        method: 'PUT',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(payload)\n      });\n      const data = await res.json();\n\n      if (!data.success) throw new Error(data.message || 'Failed to update club');\n\n      showAlert('✨ Club updated successfully!', 'success');\n      setTimeout(() => {\n        window.location.href = `club-details.html?id=${clubId}`;\n      }, 900);\n    } catch (err) {\n      console.error('Error updating club:', err);\n      showAlert(err.message, 'danger');\n    } finally {\n      submitBtn.disabled = false;\n      submitBtn.textContent = originalText;\n    }\n  });\n}\n\n// ----------------------------------------------------------------------------\n// 3. ADD MEMBER FORM\n// ----------------------------------------------------------------------------\nfunction initAddMemberForm() {\n  const form = document.getElementById('addMemberForm');\n\n  form.addEventListener('submit', async (e) => {\n    e.preventDefault();\n\n    const submitBtn = form.querySelector('button[type=\"submit\"]');\n    const originalText = submitBtn.textContent;\n    submitBtn.disabled = true;\n    submitBtn.textContent = 'Registering Student...';\n\n    const payload = {\n      full_name: document.getElementById('memberName').value.trim(),\n      usn: document.getElementById('memberUsn').value.trim().toUpperCase(),\n      email: document.getElementById('memberEmail').value.trim().toLowerCase(),\n      phone: document.getElementById('memberPhone').value.trim(),\n      course: document.getElementById('memberCourse').value.trim(),\n      semester: document.getElementById('memberSemester').value\n    };\n\n    try {\n      const res = await fetch('/api/members', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(payload)\n      });\n      const data = await res.json();\n\n      if (!data.success) throw new Error(data.message || 'Failed to add member');\n\n      fireConfetti();\n      showAlert('🎓 ' + (data.message || 'Student enrolled successfully!'), 'success');\n      form.reset();\n\n      setTimeout(() => {\n        window.location.href = 'members.html';\n      }, 1100);\n    } catch (err) {\n      console.error('Error registering member:', err);\n      showAlert(err.message, 'danger');\n    } finally {\n      submitBtn.disabled = false;\n      submitBtn.textContent = originalText;\n    }\n  });\n}\n\n// ----------------------------------------------------------------------------\n// 4. ADD EVENT FORM with Live Preview\n// ----------------------------------------------------------------------------\nasync function initAddEventForm() {\n  const form = document.getElementById('addEventForm');\n  const clubSelect = document.getElementById('eventClubSelect');\n  const titleInput = document.getElementById('eventTitle');\n  const dateInput = document.getElementById('eventDateTime');\n  const venueInput = document.getElementById('eventVenue');\n  const descInput = document.getElementById('eventDesc');\n  const previewContainer = document.getElementById('liveEventPreview');\n\n  const urlParams = new URLSearchParams(window.location.search);\n  const preselectedClubId = urlParams.get('club_id');\n\n  try {\n    const res = await fetch('/api/clubs');\n    const data = await res.json();\n    const clubs = data.data || [];\n\n    if (clubs.length === 0) {\n      clubSelect.innerHTML = '<option value=\"\">No clubs available. Please add a club first.</option>';\n    } else {\n      clubSelect.innerHTML = '<option value=\"\">-- Select Organizing Club --</option>' +\n        clubs.map(c => `\n          <option value=\"${c.club_id}\" ${preselectedClubId && String(preselectedClubId) === String(c.club_id) ? 'selected' : ''}>\n            ${escapeHTML(c.club_name)} (${escapeHTML(c.category)})\n          </option>\n        `).join('');\n    }\n  } catch (err) {\n    console.error('Error loading clubs:', err);\n    clubSelect.innerHTML = '<option value=\"\">Failed to load clubs</option>';\n  }\n\n  // Pre-set event date to tomorrow at 10:00 AM\n  if (dateInput && !dateInput.value) {\n    const tomorrow = new Date();\n    tomorrow.setDate(tomorrow.getDate() + 1);\n    tomorrow.setHours(10, 0, 0, 0);\n    const pad = n => String(n).padStart(2, '0');\n    dateInput.value = `${tomorrow.getFullYear()}-${pad(tomorrow.getMonth() + 1)}-${pad(tomorrow.getDate())}T${pad(tomorrow.getHours())}:${pad(tomorrow.getMinutes())}`;\n  }\n\n  function updateEventPreview() {\n    if (!previewContainer) return;\n    const title = (titleInput && titleInput.value.trim()) || 'Event Title Preview';\n    const dateVal = (dateInput && dateInput.value) || '';\n    const dateParts = getEventDateParts(dateVal);\n    const venue = (venueInput && venueInput.value.trim()) || 'Auditorium / Campus Venue';\n    const desc = (descInput && descInput.value.trim()) || 'Event agenda, schedule, and attendee information...';\n    const selectedClubText = clubSelect.options[clubSelect.selectedIndex]?.text || 'Organizing Club';\n\n    previewContainer.innerHTML = `\n      <div class=\"card event-card\">\n        <div class=\"card-header\">\n          <div class=\"event-ticket-top\">\n            <div class=\"calendar-box\">\n              <div class=\"calendar-month\">${dateParts.month}</div>\n              <div class=\"calendar-day\">${dateParts.day}</div>\n            </div>\n            <div>\n              <h4 class=\"card-title\">${escapeHTML(title)}</h4>\n              <div style=\"font-size: 0.8rem; font-weight: 700; color: var(--primary); margin-top: 0.25rem;\">\n                🏛️ ${escapeHTML(selectedClubText)}\n              </div>\n            </div>\n          </div>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"card-desc\">${escapeHTML(desc)}</p>\n          <div class=\"card-meta\">\n            <div class=\"meta-item\"><span>📍 Venue:</span> <strong>${escapeHTML(venue)}</strong></div>\n            <div class=\"meta-item\"><span>🕒 Time:</span> <strong>${formatDateTime(dateVal)}</strong></div>\n          </div>\n        </div>\n        <div class=\"card-footer\">\n          <span class=\"btn btn-primary btn-sm\" style=\"pointer-events: none; opacity: 0.7;\">🎟️ Register</span>\n        </div>\n      </div>\n    `;\n  }\n\n  if (titleInput) titleInput.addEventListener('input', updateEventPreview);\n  if (dateInput) dateInput.addEventListener('input', updateEventPreview);\n  if (venueInput) venueInput.addEventListener('input', updateEventPreview);\n  if (descInput) descInput.addEventListener('input', updateEventPreview);\n  if (clubSelect) clubSelect.addEventListener('change', updateEventPreview);\n  updateEventPreview();\n\n  form.addEventListener('submit', async (e) => {\n    e.preventDefault();\n\n    const submitBtn = form.querySelector('button[type=\"submit\"]');\n    const originalText = submitBtn.textContent;\n    submitBtn.disabled = true;\n    submitBtn.textContent = 'Publishing Event...';\n\n    const payload = {\n      club_id: clubSelect.value,\n      title: titleInput.value.trim(),\n      event_date: dateInput.value,\n      venue: venueInput.value.trim(),\n      description: descInput.value.trim()\n    };\n\n    try {\n      const res = await fetch('/api/events', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(payload)\n      });\n      const data = await res.json();\n\n      if (!data.success) throw new Error(data.message || 'Failed to create event');\n\n      fireConfetti();\n      showAlert('🎉 ' + (data.message || 'Event scheduled successfully!'), 'success');\n      form.reset();\n\n      setTimeout(() => {\n        window.location.href = 'events.html';\n      }, 1100);\n    } catch (err) {\n      console.error('Error adding event:', err);\n      showAlert(err.message, 'danger');\n    } finally {\n      submitBtn.disabled = false;\n      submitBtn.textContent = originalText;\n    }\n  });\n}\n\n// ----------------------------------------------------------------------------\n// 5. JOIN CLUB FORM\n// ----------------------------------------------------------------------------\nasync function initJoinClubForm() {\n  const form = document.getElementById('joinClubForm');\n  const memberSelect = document.getElementById('joinMemberSelect');\n  const clubSelect = document.getElementById('joinClubSelect');\n  const joinDateInput = document.getElementById('joinDate');\n\n  if (joinDateInput && !joinDateInput.value) {\n    joinDateInput.value = new Date().toISOString().slice(0, 10);\n  }\n\n  const urlParams = new URLSearchParams(window.location.search);\n  const preselectedMemberId = urlParams.get('member_id');\n  const preselectedClubId = urlParams.get('club_id');\n\n  try {\n    const [membersRes, clubsRes] = await Promise.all([\n      fetch('/api/members'),\n      fetch('/api/clubs')\n    ]);\n\n    const [membersData, clubsData] = await Promise.all([\n      membersRes.json(),\n      clubsRes.json()\n    ]);\n\n    const members = membersData.data || [];\n    const clubs = clubsData.data || [];\n\n    if (members.length === 0) {\n      memberSelect.innerHTML = '<option value=\"\">No members found. Please register a student first.</option>';\n    } else {\n      memberSelect.innerHTML = '<option value=\"\">-- Select Student / Member --</option>' +\n        members.map(m => `\n          <option value=\"${m.member_id}\" ${preselectedMemberId && String(preselectedMemberId) === String(m.member_id) ? 'selected' : ''}>\n            ${escapeHTML(m.full_name)} (${escapeHTML(m.usn)} - ${escapeHTML(m.course)})\n          </option>\n        `).join('');\n    }\n\n    if (clubs.length === 0) {\n      clubSelect.innerHTML = '<option value=\"\">No clubs found. Please create a club first.</option>';\n    } else {\n      clubSelect.innerHTML = '<option value=\"\">-- Select Club to Join --</option>' +\n        clubs.map(c => `\n          <option value=\"${c.club_id}\" ${preselectedClubId && String(preselectedClubId) === String(c.club_id) ? 'selected' : ''}>\n            ${escapeHTML(c.club_name)} (${escapeHTML(c.category)})\n          </option>\n        `).join('');\n    }\n  } catch (err) {\n    console.error('Error loading options:', err);\n    showAlert('Error loading members or clubs list: ' + err.message, 'danger');\n  }\n\n  form.addEventListener('submit', async (e) => {\n    e.preventDefault();\n\n    const submitBtn = form.querySelector('button[type=\"submit\"]');\n    const originalText = submitBtn.textContent;\n    submitBtn.disabled = true;\n    submitBtn.textContent = 'Enrolling Member...';\n\n    const payload = {\n      member_id: memberSelect.value,\n      club_id: clubSelect.value,\n      role: document.getElementById('joinRole').value,\n      joined_on: joinDateInput.value\n    };\n\n    try {\n      const res = await fetch('/api/memberships', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(payload)\n      });\n      const data = await res.json();\n\n      if (!data.success) throw new Error(data.message || 'Failed to join club');\n\n      fireConfetti();\n      showAlert('🤝 ' + (data.message || 'Member joined club successfully!'), 'success');\n      form.reset();\n\n      setTimeout(() => {\n        window.location.href = `club-details.html?id=${payload.club_id}`;\n      }, 1100);\n    } catch (err) {\n      console.error('Error joining club:', err);\n      showAlert(err.message, 'danger');\n    } finally {\n      submitBtn.disabled = false;\n      submitBtn.textContent = originalText;\n    }\n  });\n}\n",
  "js/main.js": "// ============================================================================\n// main.js - Ultra-Interactive UI Utilities & Animations\n// ============================================================================\n// Powers dynamic interactions: animated number counters, button click ripples,\n// celebratory confetti bursts, event calendar blocks, and copy-to-clipboard.\n// ============================================================================\n\n// Intercept all fetch() calls to bypass tunnel reminders and handle cloud proxies\n(function() {\n  const originalFetch = window.fetch;\n  window.fetch = function(...args) {\n    let [resource, config] = args;\n    config = config || {};\n    config.headers = config.headers || {};\n    if (typeof Headers !== 'undefined' && config.headers instanceof Headers) {\n      if (!config.headers.has('Bypass-Tunnel-Reminder')) {\n        config.headers.set('Bypass-Tunnel-Reminder', 'true');\n      }\n    } else {\n      config.headers['Bypass-Tunnel-Reminder'] = 'true';\n    }\n    return originalFetch(resource, config);\n  };\n})();\n\n// ----------------------------------------------------------------------------\n// 1. Toast Notification System with Animation & Progress\n// ----------------------------------------------------------------------------\nfunction showAlert(message, type = 'success') {\n  let container = document.querySelector('.alert-container');\n  if (!container) {\n    container = document.createElement('div');\n    container.className = 'alert-container';\n    document.body.appendChild(container);\n  }\n\n  const alert = document.createElement('div');\n  alert.className = `alert alert-${type}`;\n\n  const icon = type === 'success' ? '✨' : type === 'danger' ? '⚠️' : 'ℹ️';\n\n  alert.innerHTML = `\n    <div style=\"display: flex; align-items: center; gap: 0.65rem;\">\n      <span style=\"font-size: 1.25rem;\">${icon}</span>\n      <span>${escapeHTML(message)}</span>\n    </div>\n    <button style=\"background:none; border:none; cursor:pointer; font-size: 1.25rem; color:inherit; opacity: 0.7;\" onclick=\"this.parentElement.remove()\">&times;</button>\n  `;\n\n  container.appendChild(alert);\n\n  setTimeout(() => {\n    alert.style.transition = 'all 0.4s ease';\n    alert.style.opacity = '0';\n    alert.style.transform = 'translateX(100%)';\n    setTimeout(() => alert.remove(), 400);\n  }, 4500);\n}\n\n// ----------------------------------------------------------------------------\n// 2. Animated Number Counter (e.g. 0 -> 24)\n// ----------------------------------------------------------------------------\nfunction animateCounter(element, target, duration = 1200) {\n  if (!element) return;\n  const targetNum = parseInt(target, 10);\n  if (isNaN(targetNum) || targetNum <= 0) {\n    element.textContent = target;\n    return;\n  }\n\n  let startTimestamp = null;\n  const step = (timestamp) => {\n    if (!startTimestamp) startTimestamp = timestamp;\n    const progress = Math.min((timestamp - startTimestamp) / duration, 1);\n    // Ease out cubic\n    const currentVal = Math.floor((1 - Math.pow(1 - progress, 3)) * targetNum);\n    element.textContent = currentVal;\n    if (progress < 1) {\n      window.requestAnimationFrame(step);\n    } else {\n      element.textContent = targetNum;\n    }\n  };\n  window.requestAnimationFrame(step);\n}\n\n// ----------------------------------------------------------------------------\n// 3. Button Click Ripple Effect\n// ----------------------------------------------------------------------------\nfunction initButtonRipples() {\n  document.addEventListener('click', (e) => {\n    const btn = e.target.closest('.btn');\n    if (!btn) return;\n\n    const rect = btn.getBoundingClientRect();\n    const ripple = document.createElement('span');\n    ripple.className = 'ripple';\n\n    const size = Math.max(rect.width, rect.height);\n    ripple.style.width = ripple.style.height = `${size}px`;\n    ripple.style.left = `${e.clientX - rect.left - size / 2}px`;\n    ripple.style.top = `${e.clientY - rect.top - size / 2}px`;\n\n    btn.appendChild(ripple);\n    setTimeout(() => ripple.remove(), 600);\n  });\n}\n\n// ----------------------------------------------------------------------------\n// 4. Celebratory Confetti Burst Animation (Pure JS, Lightweight Canvas)\n// ----------------------------------------------------------------------------\nfunction fireConfetti() {\n  let canvas = document.getElementById('confettiCanvas');\n  if (!canvas) {\n    canvas = document.createElement('canvas');\n    canvas.id = 'confettiCanvas';\n    document.body.appendChild(canvas);\n  }\n\n  const ctx = canvas.getContext('2d');\n  canvas.width = window.innerWidth;\n  canvas.height = window.innerHeight;\n\n  const particles = [];\n  const colors = ['#4f46e5', '#06b6d4', '#10b981', '#f59e0b', '#ec4899', '#8b5cf6'];\n\n  for (let i = 0; i < 90; i++) {\n    particles.push({\n      x: canvas.width / 2,\n      y: canvas.height * 0.4,\n      vx: (Math.random() - 0.5) * 16,\n      vy: (Math.random() - 0.8) * 14,\n      size: Math.random() * 8 + 4,\n      color: colors[Math.floor(Math.random() * colors.length)],\n      rotation: Math.random() * 360,\n      vRotation: (Math.random() - 0.5) * 12,\n      opacity: 1\n    });\n  }\n\n  let animationFrame;\n  function updateConfetti() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    let alive = false;\n\n    particles.forEach(p => {\n      p.x += p.vx;\n      p.y += p.vy;\n      p.vy += 0.35; // Gravity\n      p.vx *= 0.98; // Friction\n      p.rotation += p.vRotation;\n      p.opacity -= 0.012;\n\n      if (p.opacity > 0) {\n        alive = true;\n        ctx.save();\n        ctx.translate(p.x, p.y);\n        ctx.rotate((p.rotation * Math.PI) / 180);\n        ctx.globalAlpha = p.opacity;\n        ctx.fillStyle = p.color;\n        ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);\n        ctx.restore();\n      }\n    });\n\n    if (alive) {\n      animationFrame = requestAnimationFrame(updateConfetti);\n    } else {\n      ctx.clearRect(0, 0, canvas.width, canvas.height);\n    }\n  }\n\n  updateConfetti();\n}\n\n// ----------------------------------------------------------------------------\n// 5. Date & Time Helpers\n// ----------------------------------------------------------------------------\nfunction formatDate(dateStr) {\n  if (!dateStr) return 'N/A';\n  try {\n    const d = new Date(dateStr);\n    if (isNaN(d.getTime())) return dateStr;\n    return d.toLocaleDateString('en-US', {\n      year: 'numeric',\n      month: 'short',\n      day: 'numeric'\n    });\n  } catch (e) {\n    return dateStr;\n  }\n}\n\nfunction formatDateTime(dateTimeStr) {\n  if (!dateTimeStr) return 'N/A';\n  try {\n    const d = new Date(dateTimeStr);\n    if (isNaN(d.getTime())) return dateTimeStr;\n    return d.toLocaleDateString('en-US', {\n      year: 'numeric',\n      month: 'short',\n      day: 'numeric',\n      hour: '2-digit',\n      minute: '2-digit'\n    });\n  } catch (e) {\n    return dateTimeStr;\n  }\n}\n\n// Returns Month (e.g. \"NOV\") and Day (e.g. \"15\") for ticket badge\nfunction getEventDateParts(dateTimeStr) {\n  if (!dateTimeStr) return { month: 'TBD', day: '--' };\n  try {\n    const d = new Date(dateTimeStr);\n    if (isNaN(d.getTime())) return { month: 'DATE', day: '?' };\n    const month = d.toLocaleDateString('en-US', { month: 'short' }).toUpperCase();\n    const day = d.getDate();\n    return { month, day };\n  } catch (e) {\n    return { month: 'DATE', day: '?' };\n  }\n}\n\n// Returns relative countdown label: \"In 2 days\", \"Today!\", \"Past Event\"\nfunction getEventCountdownPill(dateTimeStr) {\n  if (!dateTimeStr) return '';\n  const eventTime = new Date(dateTimeStr).getTime();\n  if (isNaN(eventTime)) return '';\n\n  const now = new Date().getTime();\n  const diffDays = Math.round((eventTime - now) / (1000 * 60 * 60 * 24));\n\n  if (diffDays < 0) {\n    return `<span class=\"countdown-pill\" style=\"background:#f1f5f9; color:#64748b;\">🏁 Past Event</span>`;\n  } else if (diffDays === 0) {\n    return `<span class=\"countdown-pill countdown-today\">🔥 Today!</span>`;\n  } else if (diffDays === 1) {\n    return `<span class=\"countdown-pill countdown-soon\">⚡ Tomorrow</span>`;\n  } else if (diffDays <= 7) {\n    return `<span class=\"countdown-pill countdown-soon\">⏳ In ${diffDays} days</span>`;\n  } else {\n    return `<span class=\"countdown-pill countdown-future\">📅 In ${diffDays} days</span>`;\n  }\n}\n\n// ----------------------------------------------------------------------------\n// 6. Avatar Initial Circles\n// ----------------------------------------------------------------------------\nfunction getAvatarHTML(name) {\n  if (!name) return `<div class=\"avatar\">👤</div>`;\n  const clean = name.trim();\n  const parts = clean.split(' ');\n  const initials = parts.length > 1\n    ? (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()\n    : clean.slice(0, 2).toUpperCase();\n\n  // Pick deterministic vibrant gradient\n  const gradients = [\n    'linear-gradient(135deg, #4f46e5, #7c3aed)',\n    'linear-gradient(135deg, #0ea5e9, #0284c7)',\n    'linear-gradient(135deg, #10b981, #059669)',\n    'linear-gradient(135deg, #f59e0b, #d97706)',\n    'linear-gradient(135deg, #ec4899, #be185d)',\n    'linear-gradient(135deg, #8b5cf6, #6d28d9)'\n  ];\n  let sum = 0;\n  for (let i = 0; i < clean.length; i++) sum += clean.charCodeAt(i);\n  const grad = gradients[sum % gradients.length];\n\n  return `<div class=\"avatar\" style=\"background: ${grad}\">${initials}</div>`;\n}\n\n// ----------------------------------------------------------------------------\n// 7. Category Badges\n// ----------------------------------------------------------------------------\nfunction getCategoryBadge(category) {\n  if (!category) return '<span class=\"badge badge-other\">General</span>';\n  const catLower = category.toLowerCase();\n  let badgeClass = 'badge-other';\n  let icon = '🏷️';\n\n  if (catLower.includes('tech') || catLower.includes('code') || catLower.includes('robot')) {\n    badgeClass = 'badge-tech';\n    icon = '💻';\n  } else if (catLower.includes('cultur') || catLower.includes('music') || catLower.includes('dance') || catLower.includes('art')) {\n    badgeClass = 'badge-cultural';\n    icon = '🎭';\n  } else if (catLower.includes('sport') || catLower.includes('fit') || catLower.includes('game')) {\n    badgeClass = 'badge-sports';\n    icon = '⚽';\n  } else if (catLower.includes('liter') || catLower.includes('debate') || catLower.includes('book')) {\n    badgeClass = 'badge-literary';\n    icon = '📚';\n  } else if (catLower.includes('social') || catLower.includes('service') || catLower.includes('nss')) {\n    badgeClass = 'badge-social';\n    icon = '🤝';\n  } else if (catLower.includes('entrepreneur') || catLower.includes('startup')) {\n    badgeClass = 'badge-literary';\n    icon = '🚀';\n  }\n\n  return `<span class=\"badge ${badgeClass}\">${icon} ${escapeHTML(category)}</span>`;\n}\n\n// ----------------------------------------------------------------------------\n// 7.5 Club Logo Generator & Description Cleaner\n// ----------------------------------------------------------------------------\nfunction getClubLogoHTML(club, size = 'md') {\n  if (!club) return `<div class=\"club-logo-badge club-logo-${size}\">🏛️</div>`;\n\n  const name = (club.club_name || '').toLowerCase();\n  const cat = (club.category || '').toLowerCase();\n  const desc = (club.description || '');\n\n  // 1. Check if description has an explicit icon like [icon:🤖] or [icon:💻]\n  let icon = null;\n  const match = desc.match(/\\[icon:([^\\]]+)\\]/);\n  if (match && match[1]) {\n    icon = match[1];\n  }\n\n  // 2. Map default icon and gradient if not explicitly provided\n  let gradient = 'linear-gradient(135deg, #4f46e5, #7c3aed)';\n\n  if (!icon) {\n    if (name.includes('code') || name.includes('developer') || name.includes('web') || name.includes('hack') || name.includes('acm') || name.includes('gdsc') || cat.includes('tech')) {\n      icon = '💻';\n      gradient = 'linear-gradient(135deg, #3b82f6, #1d4ed8)';\n    } else if (name.includes('robot') || name.includes('ai') || name.includes('drone') || name.includes('auto')) {\n      icon = '🤖';\n      gradient = 'linear-gradient(135deg, #06b6d4, #0e7490)';\n    } else if (name.includes('music') || name.includes('crescendo') || name.includes('band') || name.includes('sound')) {\n      icon = '🎵';\n      gradient = 'linear-gradient(135deg, #ec4899, #be185d)';\n    } else if (name.includes('photo') || name.includes('shutter') || name.includes('film') || name.includes('media')) {\n      icon = '📸';\n      gradient = 'linear-gradient(135deg, #f59e0b, #b45309)';\n    } else if (name.includes('entrepreneur') || name.includes('startup') || name.includes('e-cell') || cat.includes('entrepreneur')) {\n      icon = '🚀';\n      gradient = 'linear-gradient(135deg, #6366f1, #4338ca)';\n    } else if (name.includes('literary') || name.includes('debate') || name.includes('mun') || cat.includes('literary')) {\n      icon = '📚';\n      gradient = 'linear-gradient(135deg, #8b5cf6, #6d28d9)';\n    } else if (name.includes('sport') || name.includes('blitz') || name.includes('athletic') || cat.includes('sport')) {\n      icon = '⚽';\n      gradient = 'linear-gradient(135deg, #10b981, #047857)';\n    } else if (name.includes('social') || name.includes('rotaract') || name.includes('nss') || cat.includes('social')) {\n      icon = '🤝';\n      gradient = 'linear-gradient(135deg, #f97316, #c2410c)';\n    } else if (cat.includes('cultur') || name.includes('dance') || name.includes('drama')) {\n      icon = '🎭';\n      gradient = 'linear-gradient(135deg, #a855f7, #7e22ce)';\n    } else {\n      icon = '🏛️';\n      gradient = 'linear-gradient(135deg, #64748b, #334155)';\n    }\n  } else {\n    if (icon === '💻') gradient = 'linear-gradient(135deg, #3b82f6, #1d4ed8)';\n    else if (icon === '🤖') gradient = 'linear-gradient(135deg, #06b6d4, #0e7490)';\n    else if (icon === '🎵') gradient = 'linear-gradient(135deg, #ec4899, #be185d)';\n    else if (icon === '📸') gradient = 'linear-gradient(135deg, #f59e0b, #b45309)';\n    else if (icon === '🚀') gradient = 'linear-gradient(135deg, #6366f1, #4338ca)';\n    else if (icon === '📚') gradient = 'linear-gradient(135deg, #8b5cf6, #6d28d9)';\n    else if (icon === '⚽') gradient = 'linear-gradient(135deg, #10b981, #047857)';\n    else if (icon === '🤝') gradient = 'linear-gradient(135deg, #f97316, #c2410c)';\n    else if (icon === '🎨') gradient = 'linear-gradient(135deg, #a855f7, #7e22ce)';\n    else if (icon === '♟️') gradient = 'linear-gradient(135deg, #64748b, #334155)';\n  }\n\n  return `\n    <div class=\"club-logo-badge club-logo-${size}\" style=\"background: ${gradient};\">\n      <span>${icon}</span>\n    </div>\n  `;\n}\n\nfunction cleanClubDescription(desc) {\n  if (!desc) return '';\n  return desc.replace(/\\[icon:[^\\]]+\\]\\s*/g, '').trim();\n}\n\n// ----------------------------------------------------------------------------\n// 8. Copy to Clipboard Utility\n// ----------------------------------------------------------------------------\nfunction copyToClipboard(text, successMsg = 'Copied to clipboard!') {\n  if (navigator.clipboard && navigator.clipboard.writeText) {\n    navigator.clipboard.writeText(text).then(() => {\n      showAlert(successMsg, 'info');\n    });\n  } else {\n    const input = document.createElement('input');\n    input.value = text;\n    document.body.appendChild(input);\n    input.select();\n    document.execCommand('copy');\n    input.remove();\n    showAlert(successMsg, 'info');\n  }\n}\n\n// ----------------------------------------------------------------------------\n// 9. XSS Escaper\n// ----------------------------------------------------------------------------\nfunction escapeHTML(str) {\n  if (str === null || str === undefined) return '';\n  return String(str)\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;')\n    .replace(/'/g, '&#39;');\n}\n\n// ----------------------------------------------------------------------------\n// 10. Initialization\n// ----------------------------------------------------------------------------\ndocument.addEventListener('DOMContentLoaded', () => {\n  initButtonRipples();\n\n  // Mobile menu toggle\n  const menuToggle = document.querySelector('.menu-toggle');\n  const navLinks = document.querySelector('.nav-links');\n  if (menuToggle && navLinks) {\n    menuToggle.addEventListener('click', () => {\n      navLinks.classList.toggle('show');\n    });\n  }\n\n  // Active navigation link indicator\n  const currentPath = window.location.pathname;\n  const links = document.querySelectorAll('.nav-link');\n  links.forEach(link => {\n    const href = link.getAttribute('href');\n    if (href && (currentPath.endsWith(href) || (currentPath === '/' && href === 'index.html'))) {\n      link.classList.add('active');\n    }\n  });\n});\n",
  "js/members.js": "// ============================================================================\n// members.js - Interactive Students & Members Directory\n// ============================================================================\n// Includes student initials avatars, one-click USN copying, live search,\n// semester filtering, and direct club assignment shortcuts.\n// ============================================================================\n\nlet allMembers = [];\n\nasync function loadMembers() {\n  const container = document.getElementById('membersTableBody');\n  if (!container) return;\n\n  container.innerHTML = `<tr><td colspan=\"6\" style=\"text-align: center;\"><div class=\"spinner\"></div></td></tr>`;\n\n  try {\n    const res = await fetch('/api/members');\n    const result = await res.json();\n\n    if (!result.success) throw new Error(result.message || 'Failed to load members');\n\n    allMembers = result.data;\n    filterMembers();\n  } catch (err) {\n    console.error('Error loading members:', err);\n    container.innerHTML = `\n      <tr>\n        <td colspan=\"6\" style=\"text-align: center; color: var(--danger); padding: 2rem;\">\n          Failed to load members: ${escapeHTML(err.message)}\n        </td>\n      </tr>\n    `;\n  }\n}\n\nfunction renderMembers(members) {\n  const tbody = document.getElementById('membersTableBody');\n  const countBadge = document.getElementById('memberCountBadge');\n  if (!tbody) return;\n\n  if (countBadge) {\n    countBadge.textContent = `${members.length} of ${allMembers.length} enrolled`;\n  }\n\n  if (members.length === 0) {\n    tbody.innerHTML = `\n      <tr>\n        <td colspan=\"6\" style=\"text-align: center; padding: 3.5rem 1.5rem;\">\n          <div class=\"empty-state\" style=\"border: none; padding: 0;\">\n            <div class=\"empty-icon\">👥</div>\n            <div class=\"empty-title\">No Students Found</div>\n            <p>No members match the current search or filter.</p>\n            <a href=\"add-member.html\" class=\"btn btn-primary btn-sm\" style=\"margin-top: 1rem;\">+ Register Student</a>\n          </div>\n        </td>\n      </tr>\n    `;\n    return;\n  }\n\n  tbody.innerHTML = members.map(m => {\n    let clubsDisplay = '<span style=\"color: var(--text-light); font-style: italic; font-size: 0.85rem;\">No clubs yet</span>';\n    if (m.club_names) {\n      const clubsList = m.club_names.split(', ');\n      clubsDisplay = clubsList.map(c => `\n        <span class=\"badge badge-tech\" style=\"margin: 2px 2px 2px 0;\">${escapeHTML(c)}</span>\n      `).join('');\n    }\n\n    const avatar = getAvatarHTML(m.full_name);\n\n    return `\n      <tr>\n        <td>\n          <div style=\"display: flex; align-items: center; gap: 0.4rem;\">\n            <code style=\"background: #f1f5f9; padding: 2px 6px; border-radius: 4px; font-weight: 700; color: var(--dark);\">${escapeHTML(m.usn)}</code>\n            <button onclick=\"copyToClipboard('${escapeHTML(m.usn)}', 'USN copied!')\" style=\"background:none; border:none; cursor:pointer; opacity: 0.6;\" title=\"Copy USN\">📋</button>\n          </div>\n        </td>\n        <td>\n          <div class=\"member-cell\">\n            ${avatar}\n            <div>\n              <div style=\"font-weight: 700; color: var(--dark);\">${escapeHTML(m.full_name)}</div>\n              <div style=\"font-size: 0.8rem; color: var(--text-muted); display: flex; align-items: center; gap: 0.5rem; margin-top: 2px;\">\n                <a href=\"mailto:${escapeHTML(m.email)}\" style=\"color: var(--text-muted);\">✉️ ${escapeHTML(m.email)}</a>\n                ${m.phone ? `<span style=\"color: var(--text-light);\">•</span> <a href=\"tel:${escapeHTML(m.phone)}\" style=\"color: var(--text-muted);\">📞 ${escapeHTML(m.phone)}</a>` : ''}\n              </div>\n            </div>\n          </div>\n        </td>\n        <td>\n          <div style=\"font-weight: 600;\">${escapeHTML(m.course)}</div>\n        </td>\n        <td>\n          <span class=\"badge badge-other\">Sem ${escapeHTML(m.semester)}</span>\n        </td>\n        <td style=\"max-width: 250px;\">\n          ${clubsDisplay}\n        </td>\n        <td>\n          <a href=\"join-club.html?member_id=${m.member_id}\" class=\"btn btn-secondary btn-sm\" title=\"Enroll in a Club\">\n            ➕ Join Club\n          </a>\n        </td>\n      </tr>\n    `;\n  }).join('');\n}\n\nfunction filterMembers() {\n  const searchInput = document.getElementById('memberSearchInput');\n  const semesterFilter = document.getElementById('semesterFilter');\n  const clearBtn = document.getElementById('memberSearchClear');\n\n  const term = searchInput ? searchInput.value.toLowerCase().trim() : '';\n  const sem = semesterFilter ? semesterFilter.value : '';\n\n  if (clearBtn) {\n    clearBtn.style.display = term ? 'block' : 'none';\n  }\n\n  const filtered = allMembers.filter(m => {\n    const matchesSearch = \n      (m.full_name && m.full_name.toLowerCase().includes(term)) ||\n      (m.usn && m.usn.toLowerCase().includes(term)) ||\n      (m.email && m.email.toLowerCase().includes(term)) ||\n      (m.course && m.course.toLowerCase().includes(term)) ||\n      (m.club_names && m.club_names.toLowerCase().includes(term));\n\n    const matchesSem = !sem || String(m.semester) === sem;\n\n    return matchesSearch && matchesSem;\n  });\n\n  renderMembers(filtered);\n}\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  loadMembers();\n\n  const searchInput = document.getElementById('memberSearchInput');\n  if (searchInput) searchInput.addEventListener('input', filterMembers);\n\n  const semesterFilter = document.getElementById('semesterFilter');\n  if (semesterFilter) semesterFilter.addEventListener('change', filterMembers);\n\n  const clearBtn = document.getElementById('memberSearchClear');\n  if (clearBtn) clearBtn.addEventListener('click', () => {\n    if (searchInput) {\n      searchInput.value = '';\n      filterMembers();\n    }\n  });\n});\n",
  "members.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Members Directory - Campusclub</title>\n  <link rel=\"stylesheet\" href=\"css/style.css\">\n</head>\n<body>\n\n  <!-- Navigation Bar -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <a href=\"index.html\" class=\"brand\">\n        <div class=\"brand-icon\">🎓</div>\n        <div class=\"brand-name\">Campus<span>club</span></div>\n      </a>\n\n      <button class=\"menu-toggle\" aria-label=\"Toggle navigation\">☰</button>\n\n      <ul class=\"nav-links\">\n        <li><a href=\"index.html\" class=\"nav-link\">Home</a></li>\n        <li><a href=\"clubs.html\" class=\"nav-link\">Clubs</a></li>\n        <li><a href=\"members.html\" class=\"nav-link active\">Members</a></li>\n        <li><a href=\"events.html\" class=\"nav-link\">Events</a></li>\n      </ul>\n\n      <div class=\"nav-cta\">\n        <a href=\"add-member.html\" class=\"btn btn-primary btn-sm\">+ Add Member</a>\n        <a href=\"join-club.html\" class=\"btn btn-secondary btn-sm\">Join Club</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Main Content -->\n  <main class=\"main-content\">\n    <div class=\"page-header\">\n      <div>\n        <h1 class=\"page-title\">\n          Student Members Directory\n          <span id=\"memberCountBadge\" class=\"badge badge-tech\" style=\"font-size: 0.85rem; vertical-align: middle; margin-left: 0.5rem;\">Loading...</span>\n        </h1>\n        <p class=\"page-subtitle\">List of enrolled college students, their branches, semesters, and club affiliations</p>\n      </div>\n      <div style=\"display: flex; gap: 0.65rem; flex-wrap: wrap;\">\n        <a href=\"add-member.html\" class=\"btn btn-primary\">+ Register Student</a>\n        <a href=\"join-club.html\" class=\"btn btn-secondary\">Assign Club Membership</a>\n      </div>\n    </div>\n\n    <!-- Search and Semester Filter Toolbar -->\n    <div class=\"toolbar\">\n      <div class=\"search-box\">\n        <span class=\"search-icon\">🔍</span>\n        <input type=\"text\" id=\"memberSearchInput\" class=\"search-input\" placeholder=\"Search by student name, USN, course branch, or club...\">\n        <button id=\"memberSearchClear\" class=\"search-clear\" title=\"Clear search\">&times;</button>\n      </div>\n\n      <div style=\"display: flex; align-items: center; gap: 0.75rem;\">\n        <select id=\"semesterFilter\" class=\"filter-select\">\n          <option value=\"\">All Semesters</option>\n          <option value=\"1\">Semester 1</option>\n          <option value=\"2\">Semester 2</option>\n          <option value=\"3\">Semester 3</option>\n          <option value=\"4\">Semester 4</option>\n          <option value=\"5\">Semester 5</option>\n          <option value=\"6\">Semester 6</option>\n          <option value=\"7\">Semester 7</option>\n          <option value=\"8\">Semester 8</option>\n        </select>\n      </div>\n    </div>\n\n    <!-- Members Table -->\n    <div class=\"table-container\">\n      <table class=\"custom-table\">\n        <thead>\n          <tr>\n            <th>USN</th>\n            <th>Student Profile</th>\n            <th>Course / Branch</th>\n            <th>Semester</th>\n            <th>Clubs Joined</th>\n            <th>Action</th>\n          </tr>\n        </thead>\n        <tbody id=\"membersTableBody\">\n          <tr>\n            <td colspan=\"6\" style=\"text-align: center;\"><div class=\"spinner\"></div></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </main>\n\n  <!-- Footer -->\n  <footer class=\"footer\">\n    <div class=\"footer-content\">\n      <div><strong>Campusclub</strong> - College Club Management System</div>\n      <div>Built with Node.js, Express, MySQL & Vanilla JS</div>\n    </div>\n  </footer>\n\n  <script src=\"js/main.js\"></script>\n  <script src=\"js/members.js\"></script>\n</body>\n</html>\n"
};
